      if (cuando.isAfter(ahora)) {
        await programar(
          id: (r['id'] as int?) ?? 0,
          titulo: r['titulo']?.toString() ?? '',
          mensaje: r['msg']?.toString() ?? '',
          cuando: cuando,
          payload: r['payload']?.toString() ?? '',
        );
      }
    }

    // ── 4. RECORDATORIO TARDE — día del Desfile (4pm) ─────────────────────
    // Cuando ya están en la ciudad y pueden moverse hacia Av. El Poblado
    final tardeSilleteros = DateTime(2026, 8, 9, 16, 0);
    if (tardeSilleteros.isAfter(ahora)) {
      await programar(
        id: 9809,
        titulo: '🌹 El Desfile empieza en 2 horas',
        mensaje: 'Desfile de Silleteros · Av. El Poblado · 2pm → 5pm aprox.\n💡 Si no saliste todavía, este es el momento. Metro gratis · directo a Est. El Poblado.',
        cuando: tardeSilleteros,
        payload: 'rutero://feria/silleteros',
      );
    }
  }

  /// Cancela todas las notificaciones programadas
  Future<void> cancelarTodas() async {
    try {
      await _plugin.cancelAll();
    } catch (_) {}
  }

  // ── Notificaciones predefinidas de la app ──

  /// Al abrir la app después de X tiempo sin usar
  Future<void> bienvenidaDeVuelta() async {
    await mostrar(
      id: 100,
      titulo: t('🌿 ¡Bienvenido de vuelta!', '🌿 Welcome back!'),
      mensaje: t('Medellín te extraña. ¿Seguimos explorando?',
                 'Medellín misses you. Shall we keep exploring?'),
      payload: 'rutero://home',
    );
  }

  /// Al completar un sitio
  Future<void> sitioValidado(String sitioNombre, int completados, int total) async {
    final restantes = total - completados;
    await mostrar(
      id: 200 + completados,
      titulo: t('🎉 ¡Sitio validado!', '🎉 Spot validated!'),
      mensaje: restantes > 0
        ? t('$sitioNombre completado · Te quedan $restantes sitios',
            '$sitioNombre completed · $restantes spots remaining')
        : t('¡Completaste toda la ruta! Reclama tu insignia 🏆',
            'You finished the whole route! Claim your badge 🏆'),
      payload: 'rutero://home',
    );
  }

  /// Recordatorio de ruta comprada sin terminar (48h después)
  Future<void> programarRecordatorioRuta(String rutaNombre, String rutaId) async {
    final cuando = DateTime.now().add(const Duration(hours: 48));
    await programar(
      id: 300,
      titulo: t('🗺️ Tu ruta te espera', '🗺️ Your route is waiting'),
      mensaje: t('$rutaNombre · Retómala cuando quieras',
                 '$rutaNombre · Pick it up whenever you want'),
      cuando: cuando,
      payload: 'rutero://ruta/$rutaId',
    );
  }
}

// ═══════════════════════════════════════════════════════════════
//  DEEP LINK MANAGER — Enlaces profundos
// ═══════════════════════════════════════════════════════════════
// Formatos soportados:
//   rutero://ruta/NOMBRE_RUTA          → Abre detalle de ruta
//   rutero://logro/USUARIO/INSIGNIA    → Muestra logro público
//   rutero://perfil/USUARIO            → Perfil público con insignias
//   rutero://home                      → Home
// También acepta https://rutero.app/... con la misma estructura
class DeepLinkManager {
  static final DeepLinkManager _instance = DeepLinkManager._internal();
  factory DeepLinkManager() => _instance;
  DeepLinkManager._internal();

  final AppLinks _appLinks = AppLinks();
  StreamSubscription<Uri>? _sub;

  Future<void> inicializar() async {
    try {
      // 1) Capturar link que abrió la app
      final initialUri = await _appLinks.getInitialLink();
      if (initialUri != null) {
        Future.delayed(const Duration(milliseconds: 1500), () {
          procesarLink(initialUri.toString());
        });
      }
      // 2) Escuchar links mientras la app está abierta
      _sub = _appLinks.uriLinkStream.listen((uri) {
        procesarLink(uri.toString());
      });
    } catch (e) {
      debugPrint('🔴 Error inicializando deep links: $e');
    }
  }

  void procesarLink(String link) {
    try {
      final uri = Uri.parse(link);
      final segments = uri.pathSegments;
      // Detectar host o primer segmento como tipo
      final tipo = uri.host.isNotEmpty ? uri.host : (segments.isNotEmpty ? segments[0] : '');

      final ctx = kNavKey.currentContext;
      if (ctx == null) return;

      if (tipo == 'ruta' && segments.isNotEmpty) {
        final rutaNombre = Uri.decodeComponent(segments.last);
        _abrirRuta(ctx, rutaNombre);
      } else if (tipo == 'logro' && segments.length >= 2) {
        final usuario = Uri.decodeComponent(segments[segments.length - 2]);
        final insignia = Uri.decodeComponent(segments.last);
        _mostrarLogro(ctx, usuario, insignia);
      } else if (tipo == 'perfil' && segments.isNotEmpty) {
        final usuario = Uri.decodeComponent(segments.last);
        _abrirPerfilPublico(ctx, usuario);
      }
    } catch (e) {
      debugPrint('🔴 Error procesando deep link: $e');
    }
  }

  void _abrirRuta(BuildContext ctx, String rutaNombre) {
    // Busca la ruta por nombre (case-insensitive)
    final normalizado = rutaNombre.toUpperCase().replaceAll('_', ' ').replaceAll('-', ' ');
    final ruta = RutasService().rutas.firstWhere(
      (r) {
        final n = r['nombre'].toString().toUpperCase();
        return n == normalizado || n.contains(normalizado) || normalizado.contains(n);
      },
      orElse: () => <String, dynamic>{});
    if (ruta.isEmpty) return;
    Navigator.of(ctx, rootNavigator: true).push(MaterialPageRoute(
      builder: (_) => RouteDetailScreen(ruta: ruta)));
  }

  void _mostrarLogro(BuildContext ctx, String usuario, String insignia) {
    Navigator.of(ctx, rootNavigator: true).push(MaterialPageRoute(
      builder: (_) => LogroPublicoScreen(usuario: usuario, insignia: insignia)));
  }

  void _abrirPerfilPublico(BuildContext ctx, String usuario) {
    Navigator.of(ctx, rootNavigator: true).push(MaterialPageRoute(
      builder: (_) => PerfilPublicoScreen(usuario: usuario)));
  }

  /// Genera un link compartible para una ruta
  static String linkRuta(String rutaNombre) {
    final slug = rutaNombre.replaceAll(' ', '_').toUpperCase();
    return 'https://rutero.app/ruta/$slug';
  }

  /// Genera un link compartible para un logro
  static String linkLogro(String usuario, String insignia) {
    final u = Uri.encodeComponent(usuario);
    final i = Uri.encodeComponent(insignia);
    return 'https://rutero.app/logro/$u/$i';
  }

  /// Genera un link compartible para un perfil público
  static String linkPerfil(String usuario) {
    // 🚧 Beta: dominio rutero.app pendiente — usar landing actual
    return 'https://rutero-mde.web.app';
  }

  void dispose() {
    _sub?.cancel();
  }
}

