// ═══════════════════════════════════════════════════════════════════════════════
//  MÓDULO FERIA DE LAS FLORES 2026 — DATOS GLOBALES
// ═══════════════════════════════════════════════════════════════════════════════

/// Verifica si un sitio de la Feria se puede validar hoy según su fecha
/// Retorna null si puede validar, o un mensaje explicativo si no puede
String? verificarFechaEvento({
  required String rutaNombre,
  required String sitioNombre,
  required Map<String, dynamic> ruta,
}) {
  // Solo aplica a rutas de la Feria
  if (rutaNombre != 'FERIA DE LAS FLORES') return null;

  final fechas = ruta['fechasEvento'] as Map?;
  if (fechas == null) return null;

  final fechaSitio = fechas[sitioNombre];
  if (fechaSitio == null) return null; // sin restricción de día

  final List<int> fecha = List<int>.from(fechaSitio);
  final now = DateTime.now();

  if (now.month == fecha[0] && now.day == fecha[1]) {
    return null; // ✅ es el día correcto
  }

  // Calcular días restantes
  final eventoDt = DateTime(kFeriaAno, fecha[0], fecha[1]);
  final diasRestantes = eventoDt.difference(now).inDays;

  if (diasRestantes < 0) {
    return 'Este evento ya pasó · Fue el ${fecha[1]}/${fecha[0]} 🌹';
  } else if (diasRestantes == 0) {
    return null; // mismo día aunque diferente hora → permitir
  } else {
    final nombres = {
      [8, 9]: 'Desfile de Silleteros · 9 ago · 2 pm',
      [8, 8]: 'Súper Concierto + Héroes de la Patria · 8 ago',
      [8, 7]: 'Desfile Autos Clásicos y Chivas · 7 ago',
      [8, 6]: 'Final Festival de la Trova · 6 ago · 6 pm',
      [8, 3]: 'Caminata Canina · 3 ago · 10 am',
      [8, 2]: 'Desfile Avenida Primavera · 2 ago · 2 pm',
      [8, 1]: 'Feria a Ritmo de Bicicleta + Chivas · 1 ago · 10 am',
      [7, 31]: 'Concierto Inaugural · 31 jul · Noche',
    };
    final nombre = nombres.entries.firstWhere(
      (e) => e.key[0] == fecha[0] && e.key[1] == fecha[1],
      orElse: () => MapEntry(fecha, '${fecha[1]}/${fecha[0]}')).value;
    return 'Este evento es el $nombre\nVuelve ese día para validar y ganar tu insignia 🌹';
  }
}

