// Servicio de autenticación global
class AuthService {
  static final FirebaseAuth _auth = FirebaseAuth.instance;
  static final FirebaseFirestore _db = FirebaseFirestore.instance;
  static final GoogleSignIn _googleSignIn = GoogleSignIn(
    scopes: ['email', 'profile'],
    serverClientId: '300771058852-5d53fguf8gsinvj24719m0tkmnh5k7h4.apps.googleusercontent.com',
  );

  static User? get currentUser => _auth.currentUser;
  static Stream<User?> get authStateChanges => _auth.authStateChanges();

  // Login con Google
  static Future<UserCredential?> signInWithGoogle() async {
    try {
      final GoogleSignInAccount? googleUser = await _googleSignIn.signIn();
      if (googleUser == null) return null;
      final GoogleSignInAuthentication googleAuth = await googleUser.authentication;
      final credential = GoogleAuthProvider.credential(
        accessToken: googleAuth.accessToken,
        idToken: googleAuth.idToken,
      );
      final userCred = await _auth.signInWithCredential(credential)
        .timeout(const Duration(seconds: 15), onTimeout: () {
          throw FirebaseAuthException(code: 'network-request-failed');
        });
      await _guardarUsuario(userCred.user!);
      return userCred;
    } catch (e) {
      debugPrint('🔴 Google Sign-In error: $e');
      return null;
    }
  }

  // Login con email y contraseña
  static Future<UserCredential?> signInWithEmail(String email, String password) async {
    _ultimoError = null;
    try {
      final cred = await _auth.signInWithEmailAndPassword(
        email: email, password: password)
        .timeout(const Duration(seconds: 15), onTimeout: () {
          throw FirebaseAuthException(code: 'network-request-failed');
        });
      return cred;
    } on FirebaseAuthException catch (e) {
      if (e.code == 'user-not-found' || e.code == 'wrong-password' || e.code == 'invalid-credential') {
        _ultimoError = t('Email o contraseña incorrectos.','Incorrect email or password.');
      } else if (e.code == 'network-request-failed') {
        _ultimoError = t('Sin conexión o servidor lento. Intenta de nuevo.','No connection or slow server. Try again.');
      } else if (e.code == 'too-many-requests') {
        _ultimoError = t('Demasiados intentos. Espera unos minutos.','Too many attempts. Wait a few minutes.');
      } else {
        _ultimoError = 'Error: ${e.message}';
      }
      return null;
    } catch (e) {
      _ultimoError = 'Error inesperado.';
      return null;
    }
  }

  // Registro con email
  static String? _ultimoError;

  static Future<UserCredential?> registerWithEmail(String nombre, String email, String password) async {
    _ultimoError = null;
    try {
      final cred = await _auth.createUserWithEmailAndPassword(
        email: email, password: password);
      await cred.user!.updateDisplayName(nombre);
      await _guardarUsuario(cred.user!);
      return cred;
    } on FirebaseAuthException catch (e) {
      if (e.code == 'email-already-in-use') {
        _ultimoError = t('Este email ya está registrado. Intenta iniciar sesión.','This email is already registered. Try signing in.');
      } else if (e.code == 'weak-password') {
        _ultimoError = t('La contraseña es muy débil. Usa mínimo 8 caracteres.','Password is too weak. Use at least 8 characters.');
      } else if (e.code == 'invalid-email') {
        _ultimoError = t('El email no es válido.','The email is not valid.');
      } else if (e.code == 'network-request-failed') {
        _ultimoError = t('Sin conexión a internet. Verifica tu red.','No internet connection. Check your network.');
      } else {
        _ultimoError = 'Error: ${e.message}';
      }
      return null;
    } catch (e) {
      _ultimoError = t('Error inesperado. Intenta de nuevo.','Unexpected error. Please try again.');
      return null;
    }
  }

  // Cerrar sesión
  static Future<void> signOut() async {
    await _googleSignIn.signOut();
    await _auth.signOut();
  }

  // Guardar/actualizar usuario en Firestore
  static Future<void> _guardarUsuario(User user) async {
    final ref = _db.collection('usuarios').doc(user.uid);
    final doc = await ref.get();
    if (!doc.exists) {
      await ref.set({
        'nombre': user.displayName ?? 'Rutero',
        'email': user.email,
        'foto': user.photoURL,
        'fechaRegistro': FieldValue.serverTimestamp(),
        'puntosTotal': 0,
        'rutasCompletadas': 0,
        'sitiosVisitados': 0,
      });
    }
  }

  // Guardar progreso de ruta
  // FIX A: Incrementa contadores POR CADA sitio validado (no solo al completar la ruta)
  // - sitiosVisitados: +1 cada vez que se llama
  // - puntosTotal: +30 puntos por sitio individual
  // - rutasCompletadas: +1 solo al completar la ruta entera
  // - puntosTotal extra: +50 puntos de BONO al completar ruta (incentivo completista)
  static Future<void> guardarProgreso(String rutaNombre, int sitiosCompletados, int totalSitios) async {
    if (currentUser == null) return;
    final docRef = _db.collection('usuarios').doc(currentUser!.uid);

    // 1. Guardar progreso específico de esta ruta
    await docRef.collection('progreso').doc(rutaNombre).set({
      'sitiosCompletados': sitiosCompletados,
      'totalSitios': totalSitios,
      'ultimaActividad': FieldValue.serverTimestamp(),
      'completada': sitiosCompletados >= totalSitios,
    });

    // 2. Incrementar contadores globales del usuario por CADA sitio validado
    // Esto resuelve el bug donde "sitiosVisitados" siempre estaba en 0
    await docRef.update({
      'sitiosVisitados': FieldValue.increment(1),
      'puntosTotal': FieldValue.increment(30),  // 30 puntos por sitio individual
    });

    // 3. Bono extra al completar la ruta entera (+1 ruta completa, +50 puntos bono)
    if (sitiosCompletados >= totalSitios) {
      await docRef.update({
        'rutasCompletadas': FieldValue.increment(1),
        'puntosTotal': FieldValue.increment(50),
      });
      // Guardar en colección 'rutasCompletadas' para que el mapa pueda desbloquear la ruta
      await docRef.collection('rutasCompletadas').doc(rutaNombre).set({
        'fechaCompletada': FieldValue.serverTimestamp(),
        'totalSitios': totalSitios,
      }, SetOptions(merge: true));
      // 4. Desbloquear insignia en collection('insignias')
      final rutaData = RutasService().rutas.firstWhere(
        (r) => r['nombre'] == rutaNombre, orElse: () => {});
      await docRef.collection('insignias').doc(rutaNombre).set({
        'rutaNombre': rutaNombre,
        'nombre': rutaData['insignia']?.toString() ?? rutaNombre,
        'emoji': rutaData['emoji']?.toString() ?? '🏅',
        'insigniaImg': kInsigniaPorRuta[rutaNombre] ?? '',
        'puntos': (totalSitios * 30) + 50,
        'fechaDesbloqueada': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));
    }
  }

  // Guardar código de premio
  static Future<void> guardarPremio(String codigo, Map<String, dynamic> ruta) async {
    if (currentUser == null) return;
    await _db.collection('usuarios').doc(currentUser!.uid)
      .collection('premios').doc(codigo).set({
        'codigo': codigo,
        'rutaNombre': ruta['nombre'],
        'premio': ruta['premio'],
        'insignia': ruta['insignia'],
        'insigniaImg': ruta['insigniaImg'],
        'emoji': ruta['emoji'],
        'fecha': FieldValue.serverTimestamp(),
        'canjeado': false,
      });
  }

  // Obtener progreso de una ruta
  static Future<int> obtenerProgreso(String rutaNombre) async {
    if (currentUser == null) return 0;
    final doc = await _db.collection('usuarios').doc(currentUser!.uid)
      .collection('progreso').doc(rutaNombre).get();
    if (!doc.exists) return 0;
    return doc.data()?['sitiosCompletados'] ?? 0;
  }
}

