// ─────────────────────────────────────────
class LoginScreen extends StatefulWidget {
  const LoginScreen({super.key});
  @override
  State<LoginScreen> createState() => _LoginScreenState();
}

class _LoginScreenState extends State<LoginScreen> {
  final _emailCtrl = TextEditingController();
  final _passCtrl = TextEditingController();
  bool _cargando = false;
  bool _verPass = false;
  String _error = '';

  @override
  void dispose() { _emailCtrl.dispose(); _passCtrl.dispose(); super.dispose(); }

  Future<void> _loginEmail() async {
    setState(() { _cargando = true; _error = ''; });
    final cred = await AuthService.signInWithEmail(_emailCtrl.text.trim(), _passCtrl.text);
    if (mounted) {
      setState(() => _cargando = false);
      if (cred == null) {
        setState(() => _error = AuthService._ultimoError ?? t('Email o contraseña incorrectos','Incorrect email or password'));
      } else {
        Navigator.of(context, rootNavigator: true).pushAndRemoveUntil(
          MaterialPageRoute(builder: (_) => const MainShell()),
          (route) => false);
      }
    }
  }

  Future<void> _loginGoogle() async {
    setState(() { _cargando = true; _error = ''; });
    final cred = await AuthService.signInWithGoogle();
    if (mounted) {
      setState(() => _cargando = false);
      if (cred == null) {
        setState(() => _error = t('No se pudo iniciar con Google','Could not sign in with Google'));
      } else {
        Navigator.of(context, rootNavigator: true).pushAndRemoveUntil(
          MaterialPageRoute(builder: (_) => const MainShell()),
          (route) => false);
      }
    }
  }

