            const SizedBox(height: 12),

            // Campo contraseña
            _InputField(ctrl: _passCtrl, hint: tContrasena,
              emoji: '🔒', obscure: !_verPass,
              suffix: GestureDetector(
                onTap: () => setState(() => _verPass = !_verPass),
