// ─────────────────────────────────────────
//  LANG SELECT SCREEN — Selección de idioma
// ─────────────────────────────────────────
class LangSelectScreen extends StatefulWidget {
  const LangSelectScreen({super.key});
  @override
  State<LangSelectScreen> createState() => _LangSelectScreenState();
}

class _LangSelectScreenState extends State<LangSelectScreen> {
  // Pre-selecciona el idioma ya detectado en main() según el país del dispositivo
  String _selected = kLang;

  void _continuar() {
    setLang(_selected);
    final visto = _checkOnboardingVisto();
    // FIX 30/06/2026: se elimina BetaWelcomeScreen del flujo — va directo a login.
    // Causaba bug de botón tapado por barra de navegación en Android 15 (3 botones).
    final destino = visto ? const WelcomeScreen() : const OnboardingScreen();
    Navigator.of(context).pushReplacement(PageRouteBuilder(
      pageBuilder: (_, __, ___) => destino,
      transitionsBuilder: (_, anim, __, child) => FadeTransition(opacity: anim, child: child),
      transitionDuration: const Duration(milliseconds: 500),
    ));
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: kDark2,
      body: Container(
        decoration: const BoxDecoration(
          gradient: LinearGradient(
            begin: Alignment.topLeft, end: Alignment.bottomRight,
            colors: [Color(0xFF060A04), Color(0xFF0F1A0A), Color(0xFF060A04)])),
        child: SafeArea(child: Padding(
          padding: const EdgeInsets.all(32),
          child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [
            // Logo
            Container(width: 90, height: 90,
              decoration: BoxDecoration(shape: BoxShape.circle,
                boxShadow: [BoxShadow(color: kGreen.withOpacity(0.3), blurRadius: 30)]),
              child: ClipRRect(borderRadius: BorderRadius.circular(90),
                child: Image.asset('assets/images/logo_splash.png', fit: BoxFit.cover,
                  errorBuilder: (_, __, ___) => const Text('🌿', style: TextStyle(fontSize: 36))))),
            const SizedBox(height: 24),
            const Text('RUTERO MDE', style: TextStyle(
              fontSize: 28, fontWeight: FontWeight.w900, color: kText, letterSpacing: 6)),
            const SizedBox(height: 8),
            const Text('🌐  Choose your language / Elige tu idioma',
              style: TextStyle(color: kTextMuted, fontSize: 13), textAlign: TextAlign.center),
            const SizedBox(height: 40),
            // Opción Español
            GestureDetector(
              onTap: () => setState(() => _selected = 'es'),
              child: AnimatedContainer(
                duration: const Duration(milliseconds: 200),
                width: double.infinity,
                padding: const EdgeInsets.all(18),
                margin: const EdgeInsets.only(bottom: 14),
                decoration: BoxDecoration(
                  color: _selected == 'es' ? kGreen.withOpacity(0.15) : kCard,
                  borderRadius: BorderRadius.circular(16),
                  border: Border.all(
                    color: _selected == 'es' ? kGreen : Colors.white.withOpacity(0.08),
                    width: _selected == 'es' ? 2 : 1)),
                child: Row(children: [
                  const Text('🇨🇴', style: TextStyle(fontSize: 32)),
                  const SizedBox(width: 16),
                  Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                    const Text('Español', style: TextStyle(color: kText, fontSize: 18, fontWeight: FontWeight.w700)),
                    const Text('Continúa en español', style: TextStyle(color: kTextMuted, fontSize: 12)),
                  ])),
                  if (_selected == 'es')
                    Container(width: 24, height: 24,
                      decoration: const BoxDecoration(shape: BoxShape.circle, color: kGreen),
                      child: const Center(child: Text('✓', style: TextStyle(color: Colors.white, fontSize: 14)))),
                ]))),
            // Opción English
            GestureDetector(
              onTap: () => setState(() => _selected = 'en'),
              child: AnimatedContainer(
