/// Un contacto/punto del directorio de emergencia
class _ContactoEmergencia {
  final String nombre;
  final String nombreEN;
  final String detalle;
  final String detalleEN;
  final String telefono; // puede tener varios separados por " · "
  final String emoji;
  final String? direccionMaps; // texto de búsqueda para abrir Google Maps (Cómo llegar)
  final String? alquilerVehiculos; // ES — si el sitio renta carro/moto, útil en caso de pérdida
  final String? alquilerVehiculosEN;
  const _ContactoEmergencia({
    required this.nombre,
    required this.nombreEN,
    required this.detalle,
    required this.detalleEN,
    required this.telefono,
    required this.emoji,
    this.direccionMaps,
    this.alquilerVehiculos,
    this.alquilerVehiculosEN,
  });
}

