// ════════════════════════════════════════════════════════════════════════════
//  CAPTURA DE CAMPO (04/07/2026)
//  Solo para admin — toma fotos en sitios reales con GPS,
//  detecta el sitio y ruta más cercanos, y guarda con marca de agua.
// ════════════════════════════════════════════════════════════════════════════
class CapturasDeCampoScreen extends StatefulWidget {
  const CapturasDeCampoScreen({super.key});
  @override
  State<CapturasDeCampoScreen> createState() => _CapturasDeCampoScreenState();
}

class _CapturasDeCampoScreenState extends State<CapturasDeCampoScreen> {
  // Solo disponible para el correo admin
  static const String _adminEmail = 'paulflopezp@gmail.com';

  bool get _esAdmin {
    final user = FirebaseAuth.instance.currentUser;
    return user?.email == _adminEmail;
  }

  String _estado = '';
  String _sitioDetectado = '';
  String _rutaDetectada = '';
  bool _buscandoGPS = false;
  List<Map<String, dynamic>> _capturas = [];

  // Encuentra el sitio más cercano a la posición actual
  Map<String, dynamic>? _encontrarSitioCercano(double lat, double lng) {
    _SitioMapa? sitioCercano;
    double distanciaMinima = double.infinity;

    for (final sitio in kSitiosMapa) {
      final dLat = sitio.posicion.latitude - lat;
      final dLng = sitio.posicion.longitude - lng;
      final distancia = math.sqrt(dLat * dLat + dLng * dLng) * 111000;
      if (distancia < distanciaMinima) {
        distanciaMinima = distancia;
        sitioCercano = sitio;
      }
    }

    if (distanciaMinima <= 800 && sitioCercano != null) {
      return {'nombre': sitioCercano.nombre, 'ruta': sitioCercano.ruta, 'lat': sitioCercano.posicion.latitude, 'lng': sitioCercano.posicion.longitude};
    }
    return null;
  }

  Future<void> _detectarSitio() async {
    setState(() { _buscandoGPS = true; _estado = t('Obteniendo ubicación...', 'Getting location...'); });
    try {
      final pos = await Geolocator.getCurrentPosition(
        locationSettings: const LocationSettings(accuracy: LocationAccuracy.high, timeLimit: Duration(seconds: 15)));
      final sitio = _encontrarSitioCercano(pos.latitude, pos.longitude);
      if (sitio != null) {
        setState(() {
          _sitioDetectado = sitio['nombre']?.toString() ?? '';
          _rutaDetectada = sitio['ruta']?.toString() ?? '';
          _estado = t('📍 Sitio detectado', '📍 Site detected');
        });
      } else {
        setState(() { _estado = t('⚠️ Ningún sitio en los 800m cercanos', '⚠️ No site within 800m'); _sitioDetectado = ''; _rutaDetectada = ''; });
      }
    } catch (e) {
      setState(() { _estado = t('Error de GPS: $e', 'GPS error: $e'); });
    } finally {
      setState(() { _buscandoGPS = false; });
    }
  }

  Future<void> _tomarFoto() async {
    if (_sitioDetectado.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        backgroundColor: Colors.orange,
        content: Text(t('Primero detecta el sitio con GPS', 'First detect the site with GPS'))));
      return;
    }
    final picker = ImagePicker();
    final picked = await picker.pickImage(source: ImageSource.camera, imageQuality: 90);
    if (picked == null) return;

    // Dibujar marca de agua con datos del sitio sobre la imagen
    String pathFinal = picked.path;
    try {
      final bytes = await File(picked.path).readAsBytes();
      final codec = await ui.instantiateImageCodec(bytes);
      final frame = await codec.getNextFrame();
      final img = frame.image;
      final w = img.width.toDouble();
      final h = img.height.toDouble();

      final recorder = ui.PictureRecorder();
      final canvas = Canvas(recorder);

      // Dibujar imagen original
      canvas.drawImage(img, Offset.zero, Paint());

      // Fondo oscuro semitransparente en la parte inferior
      final bannerH = h * 0.12;
      canvas.drawRect(
        Rect.fromLTWH(0, h - bannerH, w, bannerH),
        Paint()..color = const Color(0xCC000000));

      // Logo Rutero MDE
      final paintLogo = TextPainter(
        text: TextSpan(text: '🗺️ RUTERO MDE',
          style: TextStyle(color: const Color(0xFF5BAD6F), fontSize: w * 0.028, fontWeight: FontWeight.w900)),
        textDirection: TextDirection.ltr);
      paintLogo.layout();
      paintLogo.paint(canvas, Offset(w * 0.03, h - bannerH + bannerH * 0.08));

      // Nombre del sitio
      final paintSitio = TextPainter(
        text: TextSpan(text: _sitioDetectado,
          style: TextStyle(color: Colors.white, fontSize: w * 0.032, fontWeight: FontWeight.w700)),
        textDirection: TextDirection.ltr);
      paintSitio.layout(maxWidth: w * 0.94);
      paintSitio.paint(canvas, Offset(w * 0.03, h - bannerH + bannerH * 0.32));

      // Nombre de la ruta
      final paintRuta = TextPainter(
        text: TextSpan(text: _rutaDetectada,
          style: TextStyle(color: const Color(0xFFE8C96A), fontSize: w * 0.022)),
        textDirection: TextDirection.ltr);
      paintRuta.layout(maxWidth: w * 0.94);
      paintRuta.paint(canvas, Offset(w * 0.03, h - bannerH + bannerH * 0.58));

      // Fecha
      final fecha = DateTime.now();
      final fechaStr = '${fecha.day}/${fecha.month}/${fecha.year}  ${fecha.hour.toString().padLeft(2,'0')}:${fecha.minute.toString().padLeft(2,'0')}';
      final paintFecha = TextPainter(
        text: TextSpan(text: fechaStr,
          style: TextStyle(color: Colors.white60, fontSize: w * 0.020)),
        textDirection: TextDirection.ltr);
      paintFecha.layout();
      paintFecha.paint(canvas, Offset(w * 0.03, h - bannerH + bannerH * 0.76));

      // Convertir a bytes PNG
      final picture = recorder.endRecording();
      final imgFinal = await picture.toImage(img.width, img.height);
      final byteData = await imgFinal.toByteData(format: ui.ImageByteFormat.png);
      if (byteData != null) {
        final tempDir = await getTemporaryDirectory();
        final tempFile = File('${tempDir.path}/rutero_${DateTime.now().millisecondsSinceEpoch}.png');
        await tempFile.writeAsBytes(byteData.buffer.asUint8List());
        pathFinal = tempFile.path;
      }
    } catch (e) {
      debugPrint('⚠️ No se pudo aplicar marca de agua: $e');
    }

    // Guardar en galería del celular
    bool guardadaEnGaleria = false;
    try {
      await Gal.putImage(pathFinal, album: 'Rutero MDE');
      guardadaEnGaleria = true;
    } catch (e) {
      debugPrint('⚠️ No se pudo guardar en galería: $e');
    }

    setState(() {
      _capturas.insert(0, {
        'path': pathFinal,
        'sitio': _sitioDetectado,
        'ruta': _rutaDetectada,
        'fecha': DateTime.now().toIso8601String(),
      });
      _estado = guardadaEnGaleria
        ? t('✅ Foto guardada en galería con marca de agua', '✅ Photo saved to gallery with watermark')
        : t('✅ Foto registrada (sin acceso a galería)', '✅ Photo registered (no gallery access)');
    });

    if (mounted && guardadaEnGaleria) {
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        backgroundColor: kGreen,
        content: Text(t(
          '📸 Foto guardada en álbum "Rutero MDE" con datos del sitio',
          '📸 Photo saved to "Rutero MDE" album with site data'))));
    }
  }

  @override
  Widget build(BuildContext context) {
    if (!_esAdmin) {
      return Scaffold(
        backgroundColor: kDark,
        appBar: AppBar(backgroundColor: kDark, title: Text(t('Captura de campo', 'Field capture'))),
        body: Center(child: Text(t('Solo disponible para administradores', 'Only available for admins'),
          style: const TextStyle(color: kTextMuted))));
    }

    return Scaffold(
      backgroundColor: kDark,
      appBar: AppBar(
        backgroundColor: kCard,
        title: Text(t('📸 Captura de campo', '📸 Field capture'),
          style: const TextStyle(color: kText, fontWeight: FontWeight.w800)),
        leading: IconButton(icon: const Icon(Icons.arrow_back, color: kText), onPressed: () => Navigator.pop(context)),
      ),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(20),
        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          // Info
          Container(
            padding: const EdgeInsets.all(14),
            decoration: BoxDecoration(color: kGreen.withOpacity(0.08), borderRadius: BorderRadius.circular(12),
              border: Border.all(color: kGreen.withOpacity(0.25))),
            child: Text(
              t('Detecta tu ubicación → la app identifica el sitio más cercano (máx. 800m) → toma la foto → queda registrada con el nombre del sitio y la ruta.',
                'Detect your location → the app identifies the nearest site (max. 800m) → take the photo → saved with site name and route.'),
              style: const TextStyle(color: kTextMuted, fontSize: 12, height: 1.5))),

          const SizedBox(height: 20),

          // Sitio detectado
          if (_sitioDetectado.isNotEmpty) ...[
            Container(
              padding: const EdgeInsets.all(14),
              decoration: BoxDecoration(color: kCard, borderRadius: BorderRadius.circular(12),
                border: Border.all(color: kGreen.withOpacity(0.4))),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text('📍 $_sitioDetectado',
                  style: const TextStyle(color: kText, fontSize: 15, fontWeight: FontWeight.w800)),
                const SizedBox(height: 4),
                Text(_rutaDetectada, style: const TextStyle(color: kGreen, fontSize: 11)),
              ])),
            const SizedBox(height: 12),
          ],

          // Estado
          if (_estado.isNotEmpty)
            Text(_estado, style: TextStyle(color: _estado.contains('⚠️') ? Colors.orange : kGreen, fontSize: 12)),

          const SizedBox(height: 20),

          // Botones
          Row(children: [
            Expanded(child: GestureDetector(
              onTap: _buscandoGPS ? null : _detectarSitio,
              child: Container(
                padding: const EdgeInsets.symmetric(vertical: 14),
                decoration: BoxDecoration(
                  color: kCard, borderRadius: BorderRadius.circular(12),
                  border: Border.all(color: kGreen.withOpacity(0.4))),
                child: Center(child: _buscandoGPS
                  ? const SizedBox(width: 20, height: 20, child: CircularProgressIndicator(strokeWidth: 2, color: kGreen))
                  : Text(t('📍 Detectar sitio', '📍 Detect site'),
                    style: const TextStyle(color: kGreen, fontWeight: FontWeight.w700)))))),
            const SizedBox(width: 12),
            Expanded(child: GestureDetector(
              onTap: _tomarFoto,
              child: Container(
                padding: const EdgeInsets.symmetric(vertical: 14),
                decoration: BoxDecoration(
                  gradient: LinearGradient(colors: [kGreen, kGreen.withOpacity(0.7)]),
                  borderRadius: BorderRadius.circular(12)),
                child: Center(child: Text(t('📸 Tomar foto', '📸 Take photo'),
                  style: const TextStyle(color: Colors.black, fontWeight: FontWeight.w800)))))),
          ]),

          const SizedBox(height: 28),

          // Galería de capturas de esta sesión
          if (_capturas.isNotEmpty) ...[
            Text(t('Capturas de esta sesión', 'This session captures'),
              style: const TextStyle(color: kText, fontSize: 14, fontWeight: FontWeight.w700)),
            const SizedBox(height: 12),
            ..._capturas.map((c) => Container(
              margin: const EdgeInsets.only(bottom: 10),
              padding: const EdgeInsets.all(12),
              decoration: BoxDecoration(color: kCard, borderRadius: BorderRadius.circular(12)),
              child: Row(children: [
                ClipRRect(
                  borderRadius: BorderRadius.circular(8),
                  child: Image.file(File(c['path']?.toString() ?? ''),
                    width: 60, height: 60, fit: BoxFit.cover,
                    errorBuilder: (_, __, ___) => Container(width: 60, height: 60, color: kGreen.withOpacity(0.2),
                      child: const Icon(Icons.image, color: kGreen)))),
                const SizedBox(width: 12),
                Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Text(c['sitio']?.toString() ?? '', style: const TextStyle(color: kText, fontSize: 13, fontWeight: FontWeight.w700)),
                  Text(c['ruta']?.toString() ?? '', style: const TextStyle(color: kGreen, fontSize: 10)),
                  Text((c['fecha']?.toString() ?? '').substring(0, 16).replaceAll('T', ' '),
                    style: const TextStyle(color: kTextMuted, fontSize: 10)),
                ])),
              ]))).toList(),
          ],
        ]),
      ),
    );
  }
}

class EmergenciaScreen extends StatelessWidget {
  const EmergenciaScreen({super.key});

  Future<void> _llamar(String telefono) async {
    final numeroLimpio = telefono.replaceAll(RegExp(r'[^\d+]'), '');
    final uri = Uri(scheme: 'tel', path: numeroLimpio);
    if (await canLaunchUrl(uri)) await launchUrl(uri);
  }

  Future<void> _comoLlegar(String query) async {
    final uri = Uri.parse('https://www.google.com/maps/search/?api=1&query=${Uri.encodeComponent(query)}');
    await launchUrl(uri, mode: LaunchMode.externalApplication);
  }

