/// Banner rotativo de aliados para pantallas Logros y Perfil
class _BannerAliados extends StatefulWidget {
  const _BannerAliados();
  @override
  State<_BannerAliados> createState() => _BannerAliadosState();
}

class _BannerAliadosState extends State<_BannerAliados> {
  int _indice = 0;

  // Lista de aliados para el banner — actualizar cuando haya más aliados
  static const List<Map<String, String>> _aliados = [
    {'emoji': '🛍️', 'nombre': 'Artesanías de mi Pueblo', 'desc': 'Cultura colombiana en tus manos', 'tag': 'Guatapé & Centro'},
    {'emoji': '🍽️', 'nombre': 'Villa Zócalo', 'desc': 'El cierre perfecto de tu ruta', 'tag': 'Guatapé'},
    {'emoji': '🏙️', 'nombre': 'Rooftop La Piedra', 'desc': 'Mirador gratis + consumo', 'tag': 'El Peñol'},
    {'emoji': '🚌', 'nombre': 'Alianza Local Tours', 'desc': 'Tu transporte hacia la aventura', 'tag': 'Antioquia'},
    {'emoji': '🌿', 'nombre': 'Rutero MDE', 'desc': 'Explora · Valida · Gana', 'tag': 'Tu próxima ruta te espera'},
  ];

  @override
  void initState() {
    super.initState();
    // Rotar cada 3 segundos
    Future.doWhile(() async {
      await Future.delayed(const Duration(seconds: 3));
      if (!mounted) return false;
      setState(() => _indice = (_indice + 1) % _aliados.length);
      return true;
    });
  }

  @override
  Widget build(BuildContext context) {
    final aliado = _aliados[_indice];
    final h = MediaQuery.of(context).size.height / 4;
    return AnimatedSwitcher(
      duration: const Duration(milliseconds: 500),
      transitionBuilder: (child, anim) => FadeTransition(opacity: anim, child: child),
      child: Container(
        key: ValueKey(_indice),
        height: h,
        decoration: BoxDecoration(
          gradient: LinearGradient(
            begin: Alignment.topCenter, end: Alignment.bottomCenter,
            colors: [kCard, kDark])),
        child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [
          Text(aliado['emoji']!, style: const TextStyle(fontSize: 36)),
          const SizedBox(height: 8),
          Text(aliado['nombre']!,
            style: const TextStyle(fontSize: 15, fontWeight: FontWeight.w700,
              color: kText, letterSpacing: 0.5)),
          const SizedBox(height: 4),
          Text(aliado['desc']!,
            style: const TextStyle(fontSize: 12, color: kTextMuted)),
          const SizedBox(height: 10),
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 4),
            decoration: BoxDecoration(
              color: kGreen.withOpacity(0.15),
              borderRadius: BorderRadius.circular(20),
              border: Border.all(color: kGreen.withOpacity(0.3))),
            child: Text(aliado['tag']!,
              style: const TextStyle(fontSize: 10, color: kGreen, fontWeight: FontWeight.w500))),
          const SizedBox(height: 10),
          Row(mainAxisAlignment: MainAxisAlignment.center,
            children: List.generate(_aliados.length, (i) =>
              Container(
                width: i == _indice ? 16 : 5,
                height: 5,
                margin: EdgeInsets.only(right: i < _aliados.length - 1 ? 4 : 0),
                decoration: BoxDecoration(
                  color: i == _indice ? kGold : kGold.withOpacity(0.25),
                  borderRadius: BorderRadius.circular(3))))),
        ])));
  }
}
