  final String id;
  final String nombre;
  final String tipo;             // 'restaurante', 'tienda', etc.
  final String ubicacion;
  final String beneficio;        // texto al turista: "10% desc + recuerdo"
  final int comisionPct;         // % que cobra Rutero MDE
  final String emoji;
  final String? whatsapp;        // contacto del aliado
  final String? notas;           // contexto interno
  final bool activo;             // visible en app

  const AliadoComercial({
    required this.id,
    required this.nombre,
    required this.tipo,
    required this.ubicacion,
    required this.beneficio,
    required this.comisionPct,
    this.emoji = '🤝',
    this.whatsapp,
    this.notas,
    this.activo = true,
  });
}

