/// Genera código único para validar canje en aliado.
/// Formato: RUTA-ALIADO-USUARIOID-FECHA
/// Ejemplo: GTPE-ART-A1B2-26042026
String generarCodigoAliado({
  required String rutaNombre,
  required String aliadoId,
  required String userId,
}) {
  // Extraer prefijo de ruta (3-4 letras)
  final rutaPrefix = rutaNombre
    .toUpperCase()
    .replaceAll('RUTA ', '')
    .replaceAll(RegExp(r'[^A-Z]'), '')
    .substring(0, rutaNombre.length >= 4 ? 4 : rutaNombre.length).padRight(4, 'X');

  // Prefijo de aliado (3 letras)
  final aliadoPrefix = aliadoId
    .toUpperCase()
    .replaceAll('_', '')
    .substring(0, aliadoId.length >= 3 ? 3 : aliadoId.length).padRight(3, 'X');

  // Sufijo de usuario (4 caracteres)
  final userSuffix = userId.length >= 4
    ? userId.substring(0, 4).toUpperCase()
    : userId.toUpperCase().padRight(4, 'X');

  // Fecha en formato DDMMYYYY
  final now = DateTime.now();
  final fecha = '${now.day.toString().padLeft(2, '0')}'
                '${now.month.toString().padLeft(2, '0')}'
                '${now.year}';

  return '$rutaPrefix-$aliadoPrefix-$userSuffix-$fecha';
}

/// Registra el código de aliado generado en Firestore.
/// Se guarda como "consumo pendiente" — el aliado lo confirma después
/// con el monto real consumido en su panel web.
Future<void> registrarCodigoAliado({
  required String codigo,
  required AliadoComercial aliado,
  required String rutaNombre,
}) async {
  final user = FirebaseAuth.instance.currentUser;
  if (user == null) return;
  try {
    await FirebaseFirestore.instance
      .collection('consumos_aliados')
      .add({
        'codigo': codigo,
        'aliadoId': aliado.id,
        'aliadoNombre': aliado.nombre,
        'aliadoTipo': aliado.tipo,
        'turistaId': user.uid,
        'turistaNombre': user.displayName ?? user.email?.split('@').first ?? 'Rutero',
        'turistaEmail': user.email,
        'ruta': rutaNombre,
        'comisionPct': aliado.comisionPct,
        'monto': null,           // lo llena el aliado al confirmar
        'comisionMonto': null,   // se calcula cuando el aliado confirma
        'fechaGeneracion': FieldValue.serverTimestamp(),
        'fechaConfirmacion': null,
        'estado': 'generado',    // generado → confirmado → pagado
      });
  } catch (e) {
    debugPrint('⚠️ Error registrando código aliado: $e');
  }
}

/// Convierte un color de ruta que puede venir como Color (hardcode) o String hex (Firestore)
Color kRutaColor(dynamic val, Color fallback) {
  if (val == null) return fallback;
  if (val is Color) return val;
  if (val is String) {
    final hex = val.replaceAll('#', '').trim();
    if (hex.length == 6) {
      return Color(int.parse('FF$hex', radix: 16));
    }
  }
  return fallback;
}

