class RutasService {
  static final RutasService _instance = RutasService._internal();
  factory RutasService() => _instance;
  RutasService._internal();

  List<Map<String, dynamic>> _rutas = [];
  bool _cargado = false;
  bool get cargado => _cargado;

  /// Rutas actuales — Firestore + rutas locales que no estén en Firestore
  /// Las rutas que están en Firestore (aunque se borren) NO se reinyectan desde local.
  List<Map<String, dynamic>> get rutas {
    if (!_cargado || _rutas.isEmpty) return [...kFeriaRutasCompletas]; // fallback mientras carga Firestore
    // Merge: rutas de Firestore + rutas locales que Firestore no tiene
    // EXCLUIR rutas locales que ya fueron migradas a Firestore (para evitar zombis)
    final nombresFirestore = _rutas.map((r) => r['nombre']?.toString() ?? '').toSet();
    const migradasAFirestore = {
      // ── Rutas Ciudad originales ──────────────────────────────────────
      'VIVE EL POBLADO',
      'DISEÑO MODA Y COMPRAS',
      'HUELLAS VIVAS DE EL POBLADO',
      'EL POBLADO VERDE',
      'EL POBLADO CREATIVO',
      'SABORES DE EL POBLADO',
      'NOCHE EN EL POBLADO',
      'VIVE LAURELES',
      'CENTRO PATRIMONIAL',
      'RUTA GUATAPÉ & LA PIEDRA',
      'VIVE MANRIQUE',
      'MANRIQUE CULTURA Y VIDA',
      'CENTRO ALTERNATIVO',
      'RINCONES ESCONDIDOS DE EL POBLADO',
      // ── Rutas en Firestore Y en kRutasData → usar versión Firestore ──
      'RUTA MEMORIA Y REFLEXIÓN',
      'RUTA TRANSFORMACIÓN URBANA',
      'RUTA VERDE DEL NORTE',
      'RUTA DEL METROCABLE & ARVÍ',
      'RUTA DE LOS MIRADORES',
      'DEL ORIGEN PAISA A LA MEDELLÍN MODERNA',
      'TRANVÍA CULTURAL',
      'TRANSFORMACIÓN MEMORIA E HISTORIA',
      // ── Comida Urbana ────────────────────────────────────────────────
      'SABORES DE LA 70',
      'SABORES DEL CENTRO',
      'SABOR PAISA PROFUNDO — ENVIGADO',
      'SABOR URBANO — MERCADO DEL RÍO',
      // ── Temporada ────────────────────────────────────────────────────
      'FERIA DE LAS FLORES',
      'COLOMBIAMODA — MODA & DISEÑO',
      'FESTIVAL INTERNACIONAL DE TANGO',
      'FERIA DE LA ANTIOQUEÑIDAD',
      'MEDEÍJAZZ — FESTIVAL DE JAZZ',
      'SEMANA SANTA PATRIMONIAL',
      'FIESTA DEL LIBRO Y LA CULTURA',
      'NOCHE EN LAURELES',
      'BARRIO PRADO — CULTURA Y BOHEMIA',
      'MEMORIA Y DERECHOS HUMANOS',
      'CAFÉS Y CANTINAS HISTÓRICAS DEL CENTRO',
      'TEATROS Y ESCENA DEL CENTRO',
      'ENTRE JUEGOS Y PALABRAS',
      'ENTRE SABORES RISAS Y MIL COLORES',
      'OTROS CAMINOS LAURELES',
      'FINCAS SILLETERAS',
      'FINCAS AGROTURÍSTICAS',
      // ── Alrededores ──────────────────────────────────────────────────
      'RUTA SANTA FE DE ANTIOQUIA',
      'JOYA COLONIAL OCULTA — CONCEPCIÓN',
    };
    final soloLocales = kRutasData.where((r) {
      final nombre = r['nombre']?.toString() ?? '';
      if (nombresFirestore.contains(nombre)) return false;
      if (migradasAFirestore.contains(nombre)) return false;
      return true;
    }).toList();
    // Agregar rutas completas de Feria que no estén ya en Firestore o locales
    final nombresTodos = {...nombresFirestore, ...soloLocales.map((r) => r['nombre']?.toString() ?? '')};
    final feriaExtras = kFeriaRutasCompletas.where((r) => !nombresTodos.contains(r['nombre']?.toString() ?? '')).toList();
    return [..._rutas, ...soloLocales, ...feriaExtras];
  }

  /// Lanza carga en background sin bloquear el arranque de la app.
  /// Llamar sin await en main() — la app abre instantáneamente.
  final List<VoidCallback> _listeners = [];

  void addListener(VoidCallback cb) => _listeners.add(cb);
  void removeListener(VoidCallback cb) => _listeners.remove(cb);
  void _notificar() { for (final cb in List.of(_listeners)) { cb(); } }

  /// Busca un sitio en sitiosDetalle de Firestore por nombre.
  /// Retorna el Map del sitio o null si no existe.
  Map<String, dynamic>? buscarSitioDetalle(String sitioNombre) {
    for (final ruta in _rutas) {
      final detalle = parseSitiosDetalle(ruta['sitiosDetalle']);
      for (final sitio in detalle) {
        if (sitio is Map && sitio['nombre']?.toString() == sitioNombre) {
          final m = Map<String, dynamic>.from(sitio);
          // Limpiar precios individuales de descripciones — política general
          if (m['descripcion'] is String) m['descripcion'] = _limpiarPrecioSitio(m['descripcion']?.toString() ?? '');
          if (m['descripcionEN'] is String) m['descripcionEN'] = _limpiarPrecioSitio(m['descripcionEN']?.toString() ?? '');
          if (m['tip'] is String) m['tip'] = _limpiarPrecioSitio(m['tip']?.toString() ?? '');
          if (m['tipEN'] is String) m['tipEN'] = _limpiarPrecioSitio(m['tipEN']?.toString() ?? '');
          return m;
        }
      }
    }
    return null;
  }

  /// Retorna curiosidad de sitiosDetalle como Map {'es': ..., 'en': ...}
  Map<String, String>? getCuriosidad(String sitioNombre) {
    final s = buscarSitioDetalle(sitioNombre);
    if (s == null || (s['curiosidad'] == null && s['curiosidadEN'] == null)) return null;
    return {'es': s['curiosidad'] ?? '', 'en': s['curiosidadEN'] ?? ''};
  }

  /// Retorna reto de sitiosDetalle como Map compatible con kRetosPorSitio
  Map<String, dynamic>? getReto(String sitioNombre) {
    final s = buscarSitioDetalle(sitioNombre);
    if (s == null || (s['reto'] == null && s['retoEN'] == null)) return null;
    return {
      'emoji': s['emoji'] ?? '🎯',
      'reto_es': s['reto'] ?? '',
      'reto_en': s['retoEN'] ?? '',
      'puntos': s['puntosReto'] ?? 10,
    };
  }

  /// Retorna tip de sitiosDetalle como Map {'es': ..., 'en': ..., 'emoji': ...}
  Map<String, String>? getTip(String sitioNombre) {
    final s = buscarSitioDetalle(sitioNombre);
    if (s == null || (s['tip'] == null && s['tipEN'] == null)) return null;
    return {'es': s['tip'] ?? '', 'en': s['tipEN'] ?? '', 'emoji': s['emoji'] ?? '✨'};
  }

  /// Retorna misionEpica de la ruta de Firestore
  Map<String, dynamic>? getMisionEpica(String rutaNombre) {
    for (final ruta in _rutas) {
      if (ruta['nombre']?.toString() == rutaNombre && ruta['misionEpica'] != null) {
        return {
          'nombre_es': ruta['nombre'] ?? '',
          'nombre_en': ruta['nombreEN'] ?? '',
          'descripcion_es': ruta['misionEpica'] ?? '',
          'descripcion_en': ruta['misionEpicaEN'] ?? '',
          'recompensa_es': ruta['premio'] ?? 'Insignia',
          'recompensa_en': ruta['premio'] ?? 'Badge',
          'objetivo': ruta['sitios'] ?? 5,
          'puntos': 500,
          'emoji': ruta['personaje'] ?? '🏆',
        };
      }
    }
    return null;
  }

  void cargarEnBackground() {
    Future.microtask(() async {
      QuerySnapshot<Map<String, dynamic>> snap;
      try {
        // Forzar lectura directa del servidor — evita mostrar datos
        // borrados que aún estén en la caché local persistente del SDK.
        snap = await FirebaseFirestore.instance
            .collection('rutas')
            .get(const GetOptions(source: fs.Source.serverAndCache))
            .timeout(const Duration(seconds: 15));
      } catch (e) {
        debugPrint('⚠️ RutasService: server falló, intentando caché. ' + e.toString());
        try {
          snap = await FirebaseFirestore.instance
              .collection('rutas')
              .get()
              .timeout(const Duration(seconds: 60));
        } catch (e2) {
          debugPrint('⚠️ RutasService: fallback hardcode. ' + e2.toString());
          return;
        }
      }
      try {
        if (snap.docs.isNotEmpty) {
          _rutas = snap.docs.map((d) {
            final data = d.data() as Map<String, dynamic>;
            final ruta = <String, dynamic>{'id': d.id, ...data};
            final nombre = ruta['nombre']?.toString() ?? '';
            // Enriquecer con imagen/insignia local si Firestore no las trae
            // Enriquecer con imagen local (override Firestore paths que no existen)
            final imagenLocal = kImagenPorRuta[nombre];
            if (imagenLocal != null) ruta['imagen'] = imagenLocal;

            ruta['insigniaImg'] ??= kInsigniaPorRuta[nombre];
            // Enriquecer zona si Firestore no la trae
            if (!ruta.containsKey('zona') || ruta['zona'] == null) {
              final zonaLocal = kZonaPorRuta[nombre];
              if (zonaLocal != null) ruta['zona'] = zonaLocal;
            }
            // Enriquecer con campos locales que Firestore normalmente no almacena
            // (consejos, momentoClave, descripciones, hooks, colores, etc.)
            final localData = kRutasData.firstWhere(
              (r) => r['nombre']?.toString() == nombre, orElse: () => {});
            if (localData.isNotEmpty) {
              ruta['consejos']       ??= localData['consejos'];
              ruta['consejosEN']     ??= localData['consejosEN'];
              ruta['momentoClave']   ??= localData['momentoClave'];
              ruta['momentoClaveEN'] ??= localData['momentoClaveEN'];
              ruta['hook']           ??= localData['hook'];
              ruta['hookEN']         ??= localData['hookEN'];
              ruta['descripcion']    ??= localData['descripcion'];
              ruta['descripcionEN']  ??= localData['descripcionEN'];
              ruta['mejorHora']      ??= localData['mejorHora'];
              ruta['tipoExperiencia']   ??= localData['tipoExperiencia'];
              ruta['tipoExperienciaEN'] ??= localData['tipoExperienciaEN'];
              ruta['misionEpica']    ??= localData['misionEpica'];
              ruta['misionEpicaEN']  ??= localData['misionEpicaEN'];
              ruta['color1']         ??= localData['color1'];
              ruta['color2']         ??= localData['color2'];
              ruta['acento']         ??= localData['acento'];
              ruta['tag']            ??= localData['tag'];
              ruta['antesDeSalir']   ??= localData['antesDeSalir'];
              // transporte siempre desde local — Firestore puede tener versión desactualizada
              if (localData['transporte'] != null) ruta['transporte'] = localData['transporte'];
            }
            // Enriquecer con datos de temporada local
            final tempData = kTemporadaPorRuta[nombre];
            if (tempData != null) {
              ruta['temporadaMeses'] ??= tempData['temporadaMeses'];
              ruta['temporadaInicio'] ??= tempData['temporadaInicio'];
              ruta['temporadaFin'] ??= tempData['temporadaFin'];
            }
            // Marcar rutas pausadas
            if (kRutasPausadas.contains(nombre)) {
              ruta['pausada'] ??= true;
            }
            return ruta;
          }).toList();
          // Deduplicar por nombre — si hay docs duplicados en Firestore, tomar el primero
          final seenNombres = <String>{};
          _rutas = _rutas.where((r) {
            final n = r['nombre']?.toString() ?? '';
            if (n.isEmpty || seenNombres.contains(n)) return false;
            seenNombres.add(n);
            return true;
          }).toList();
          _cargado = true;
          _notificar(); // Avisar a la UI que hay datos nuevos
        }
      } catch (e) {
        debugPrint('⚠️ RutasService: fallback hardcode. ' + e.toString());
      }
    });
  }

  /// Recarga forzada
  void recargar() { _cargado = false; cargarEnBackground(); }
}

// ─────────────────────────────────────────────────────────────────────────
//  ALIADOS SERVICE — Carga aliados desde Firestore
// ─────────────────────────────────────────────────────────────────────────
class AliadosService {
  static final AliadosService _instance = AliadosService._internal();
  factory AliadosService() => _instance;
  AliadosService._internal();

  List<Map<String, dynamic>> _aliados = [];
  bool _cargado = false;

  void cargarEnBackground() {
    Future.microtask(() async {
      try {
        final snap = await FirebaseFirestore.instance
            .collection('aliados')
            .where('activo', isEqualTo: true)
            .get()
            .timeout(const Duration(seconds: 30));
        if (snap.docs.isNotEmpty) {
          _aliados = snap.docs
              .map((d) { final data = d.data() as Map<String, dynamic>; return <String, dynamic>{'id': d.id, ...data}; })
              .toList();
          _cargado = true;
        }
      } catch (e) {
        debugPrint('⚠️ AliadosService: fallback. ' + e.toString());
      }
    });
  }

  /// Filtra aliados por ciudad activa — evita que aliados de MDE aparezcan en BTA o PPN
  /// Regla: si el aliado tiene campo 'ciudad', solo se muestra si coincide con la ciudad activa.
  /// Si no tiene campo 'ciudad', se considera global (visible en todas).
  List<Map<String, dynamic>> filtradosPorCiudad(String? ciudadActiva) {
    if (!_cargado) return [];
    if (ciudadActiva == null || ciudadActiva.isEmpty) return _aliados;
    return _aliados.where((a) {
      final ciudadAliado = a['ciudad']?.toString().trim() ?? '';
      if (ciudadAliado.isEmpty) return true; // global — visible en todas
      return ciudadAliado.toLowerCase() == ciudadActiva.toLowerCase();
    }).toList();
  }

  /// Busca el aliado asociado a una ruta por nombre
  /// Aliado general de la ruta (sin sitio específico)
  Map<String, dynamic>? aliadoParaRuta(String nombreRuta, {String? ciudadActiva}) {
    final lista = filtradosPorCiudad(ciudadActiva);
    try {
      return lista.firstWhere((a) {
        final sitio = a['sitio']?.toString().trim() ?? '';
        if (sitio.isNotEmpty) return false;
        final rutas = a['rutas'];
        if (rutas is List) {
          return rutas.any((r) => r.toString().trim().toUpperCase() == nombreRuta.trim().toUpperCase());
        }
        return false;
      });
    } catch (_) { return null; }
  }

  /// Aliados asociados a un sitio específico dentro de una ruta
  List<Map<String, dynamic>> aliadosParaSitio(String nombreRuta, String nombreSitio, {String? ciudadActiva}) {
    final lista = filtradosPorCiudad(ciudadActiva);
    return _aliados.where((a) {
      final sitio = a['sitio']?.toString().trim() ?? '';
      if (sitio.isEmpty) return false;
      // Verificar que el aliado pertenece a esta ruta
      final rutas = a['rutas'];
      bool enRuta = false;
      if (rutas is List) {
        enRuta = rutas.any((r) => r.toString().trim().toUpperCase() == nombreRuta.trim().toUpperCase());
      }
      if (!enRuta) return false;
      // Verificar que el sitio coincide
      return sitio.toUpperCase().contains(nombreSitio.trim().toUpperCase()) ||
             nombreSitio.trim().toUpperCase().contains(sitio.toUpperCase());
    }).toList();
  }
}

// Lista global de rutas — accesible desde MapScreen y RouteDetailScreen
// ignore: non_constant_identifier_names
final List<Map<String, dynamic>> kRutasData = [
  // ── Todas las rutas migradas a Firestore (22 jul 2026) ──────────────────
  // Las 15 rutas que estaban aquí fueron migradas y están bloqueadas
  // en migradasAFirestore. Se mantiene la lista vacía para compatibilidad.
  // Para agregar rutas nuevas usar admin.html → Método B o Método E.
  ];
class _HomeBodyState extends State<HomeBody> {
  String _filtroActivo = 'Ciudad';
  String _busqueda = '';
  final TextEditingController _searchCtrl = TextEditingController();

  // ── Detección de ciudad por GPS (23/05/2026) ──
  _CiudadRegistrada? _ciudadDetectada;
  bool _cargandoCiudad = true;

  @override
  void initState() {
    super.initState();
    _detectarCiudad();
    // Escuchar cuando RutasService termina de cargar de Firestore
    RutasService().addListener(_onRutasCargadas);
  }

  void _onRutasCargadas() {
    if (mounted) setState(() {}); // Refrescar UI con rutas de Firestore
  }

  Future<void> _detectarCiudad() async {
    final ciudad = await detectarCiudadActual();
    if (mounted) setState(() { _ciudadDetectada = ciudad; _cargandoCiudad = false; });
  }

  // Rutas filtradas por ciudad detectada + filtro de zona activo
  List<Map<String, dynamic>> get _rutas {
    final porCiudad = filtrarRutasPorCiudad(_ciudadDetectada);
    return porCiudad;
  }

  @override
  void dispose() {
    _searchCtrl.dispose();
    RutasService().removeListener(_onRutasCargadas);
    super.dispose();
  }
  void _onTabTap(int index) {
    tabNotifier.value = index;
  }

  String _saludoHora() {
    final h = DateTime.now().hour;
    if (h < 12) return t('BUENOS DÍAS', 'GOOD MORNING');
    if (h < 18) return t('BUENAS TARDES', 'GOOD AFTERNOON');
    return t('BUENAS NOCHES', 'GOOD EVENING');
  }

  bool _rutaActivaEvento(Map<String, dynamic> ruta) {
    final recurrente = ruta['eventoRecurrente'];
    if (recurrente == 'fines_semana') {
      final dia = DateTime.now().weekday;
      return dia == DateTime.friday || dia == DateTime.saturday || dia == DateTime.sunday;
    }
    return _rutaActiva(ruta);
  }

  bool _rutaActiva(Map<String, dynamic> ruta) {
    // 🧪 Modo demo — admin ve todas las rutas de temporada activas
    if (kModoDemo) return true;
    final ahora = DateTime.now();
    final List? inicio = ruta['temporadaInicio'] as List?;
    final List? fin = ruta['temporadaFin'] as List?;

    // Si tiene rango exacto → usar rango (+7 días antes para promocionar)
    if (inicio != null && fin != null && inicio.length == 2 && fin.length == 2) {
      final int mI = inicio[0] as int, dI = inicio[1] as int;
      final int mF = fin[0] as int, dF = fin[1] as int;
      DateTime dtInicio = DateTime(ahora.year, mI, dI);
      DateTime dtFin = DateTime(ahora.year, mF, dF, 23, 59);
      // Rango que cruza año (ej: 1 dic → 15 ene)
      if (mF < mI) {
        // Si estamos antes del fin del próximo año, ajusta
        if (ahora.month <= mF) {
          dtInicio = DateTime(ahora.year - 1, mI, dI);
        } else {
          dtFin = DateTime(ahora.year + 1, mF, dF, 23, 59);
        }
      }
      // 7 días antes se puede ver (preview)
      final dtPreview = dtInicio.subtract(const Duration(days: 7));
      return ahora.isAfter(dtPreview) && ahora.isBefore(dtFin);
    }

    // Fallback al sistema viejo por meses
    final List<int> meses = List<int>.from(ruta['temporadaMeses'] ?? []);
    if (meses.isEmpty) return false; // Sin fechas de temporada → mostrar como próximamente
    return meses.contains(ahora.month);
  }

  String _proximaActivacion(Map<String, dynamic> ruta) {
    final List? inicio = ruta['temporadaInicio'] as List?;
    if (inicio != null && inicio.length == 2) {
      final int m = inicio[0] as int, d = inicio[1] as int;
      return '$d de ${_mesNombre(m)}';
    }
    final List<int> meses = List<int>.from(ruta['temporadaMeses'] ?? []);
    if (meses.isEmpty) return '';
    return meses.map((m) => _mesNombre(m)).join(' · ');
  }

  int _diasParaActivacion(Map<String, dynamic> ruta) {
    final ahora = DateTime.now();
    final List? inicio = ruta['temporadaInicio'] as List?;

    if (inicio != null && inicio.length == 2) {
      final int m = inicio[0] as int, d = inicio[1] as int;
      DateTime prox = DateTime(ahora.year, m, d);
      if (prox.isBefore(ahora)) prox = DateTime(ahora.year + 1, m, d);
      return prox.difference(ahora).inDays;
    }

    final List<int> meses = List<int>.from(ruta['temporadaMeses'] ?? []);
    if (meses.isEmpty) return 0;
    int min = 999;
    for (final m in meses) {
      DateTime prox = DateTime(ahora.year, m, 1);
      if (prox.isBefore(ahora)) prox = DateTime(ahora.year + 1, m, 1);
      final d = prox.difference(ahora).inDays;
      if (d < min) min = d;
    }
    return min;
  }

  // ── Orden fijo para rutas Ciudad (actualizado 25 jul 2026) ──────────────
  static const List<String> _ordenCiudad = [
    'RUTA TRANSFORMACIÓN URBANA',
    'RUTA VERDE DEL NORTE',
    'RUTA DEL METROCABLE & ARVÍ',
    'CENTRO ALTERNATIVO',
    'DEL ORIGEN PAISA A LA MEDELLÍN MODERNA',
    // Las demás se ordenan después en el orden que lleguen de Firestore
  ];

  List<Map<String, dynamic>> get _rutasFiltradas {
    // Si hay búsqueda activa → buscar en TODAS las rutas (sin filtro de ciudad)
    final base = _busqueda.isNotEmpty ? RutasService().rutas : _rutas;
    final filtered = base.where((r) {
      if (_busqueda.isNotEmpty) {
        final q = _busqueda.toLowerCase();
        final nombre = r['nombre'].toString().toLowerCase();
        final sub = r['subtitulo'].toString().toLowerCase();
        final sitios = ((r['sitiosList'] as List?)?.map((s) => s.toString()).toList() ?? []).join(' ').toLowerCase();
        final ciudad = r['ciudad'].toString().toLowerCase();
        if (!nombre.contains(q) && !sub.contains(q) &&
            !sitios.contains(q) && !ciudad.contains(q)) return false;
      }
      if (_filtroActivo == 'Ciudad' && r['zona'] != 'Ciudad') return false;
      if (_filtroActivo == 'Alrededores' && r['zona'] != 'Alrededores') return false;
      if (_filtroActivo == 'Temporada' && r['zona'] != 'Temporada') return false;
      if (_filtroActivo == 'Comida Urbana' && r['zona'] != 'Comida Urbana') return false;
      if (_filtroActivo == 'Eventos' && r['zona'] != 'Eventos') return false;
      return true;
    }).toList();

    // Aplicar orden fijo para rutas Ciudad
    if (_filtroActivo == 'Ciudad' && _busqueda.isEmpty) {
      filtered.sort((a, b) {
        final ia = _ordenCiudad.indexOf(a['nombre']?.toString() ?? '');
        final ib = _ordenCiudad.indexOf(b['nombre']?.toString() ?? '');
        if (ia == -1 && ib == -1) return 0;
        if (ia == -1) return 1;
        if (ib == -1) return -1;
        return ia.compareTo(ib);
      });
    }
    return filtered;
  }

