              else
                ..._rutasFiltradas.map((r) { final esPausada = r['pausada'] == true; final esTemporada = r['zona'] == 'Temporada' || r['zona'] == 'Eventos'; final activa = !esPausada && (!esTemporada || _rutaActiva(r)); return _RouteCard(
                  ruta: r, activa: activa,
