                subtitulo: '${_rutas.where((r) => r["zona"] == "Ciudad").length} ${t("rutas disponibles","routes available")}'),
              const SizedBox(height: 10),
              // ── Agrupar por sectores de Medellín ──
              ...(() {
                final rutasCiudad = _rutas.where((r) {
                  if (r['zona'] != 'Ciudad') return false;
                  if (_ciudadDetectada == null) return true;
                  final rutaCiudad = r['ciudad']?.toString() ?? 'Medellín';
                  return rutaCiudad == _ciudadDetectada!.ciudad;
                }).toList();

                // Detectar sector por nombre de ruta
                String _sector(Map<String, dynamic> r) {
                  final n = r['nombre']?.toString() ?? '';
                  if (n.contains('POBLADO') || n.contains('HUELLAS VIVAS')) return '📍 El Poblado';
                  if (n.contains('LAURELES') || n.contains('LA 70')) return '🌿 Laureles';
                  if (n.contains('CENTRO') || n.contains('PATRIMONIAL') || n.contains('REPUBLICANO') || n.contains('TRANVÍA') || n.contains('ORIGEN PAISA')) return '🏛️ Centro';
                  if (n.contains('MANRIQUE') || n.contains('TRANSFORMACIÓN')) return '🎨 Manrique & Norte';
                  return '🗺️ Medellín';
                }

                // Orden fijo de sectores: primero las rutas urbanas históricas, Poblado y Laureles al final
                const ordenSectores = [
                  '🗺️ Medellín',
                  '🎨 Manrique & Norte',
                  '🏛️ Centro',
                  '📍 El Poblado',
                  '🌿 Laureles',
                ];

                final sectores = <String>[];
                final porSector = <String, List<Map<String, dynamic>>>{};
                for (final r in rutasCiudad) {
                  final s = _sector(r);
                  if (!sectores.contains(s)) sectores.add(s);
                  porSector.putIfAbsent(s, () => []).add(r);
                }
                // Aplicar orden fijo — Poblado y Laureles siempre al final
                final sectoresOrdenados = ordenSectores.where((s) => porSector.containsKey(s)).toList();
                // Agregar cualquier sector no contemplado en el orden
                for (final s in sectores) {
                  if (!sectoresOrdenados.contains(s)) sectoresOrdenados.add(s);
                }

                final widgets = <Widget>[];
                for (final sector in sectoresOrdenados) {
                  widgets.add(Padding(
                    padding: const EdgeInsets.only(top: 12, bottom: 6, left: 4),
                    child: Text(sector,
                      style: const TextStyle(color: kGold, fontSize: 13,
                        fontWeight: FontWeight.w800, letterSpacing: 1.2))));
                  for (final r in porSector[sector]!) {
                    final pausada = r['pausada'] == true;
                    widgets.add(_RouteCard(
                      ruta: r, activa: !pausada,
                      proximaActivacion: pausada ? (r['tagPausada'] ?? '🚧 Próximamente') : '',
                      onTap: pausada ? null : () => RuteroNav.push(context, RouteDetailScreen(ruta: r))));
                  }
                }
                return widgets;
              })(),
            ] else if (_filtroActivo == 'Alrededores') ...[
              _SectionHeader(
                titulo: t('🗻 ALREDEDORES','🗻 SURROUNDINGS'),
                subtitulo: '${_rutas.where((r) => r["zona"] == "Alrededores").length} ${t("rutas disponibles","routes available")}'),
              const SizedBox(height: 10),
              ..._rutas.where((r) => r['zona'] == 'Alrededores' && (_ciudadDetectada == null || (r['ciudad']?.toString() ?? 'Medellín') == _ciudadDetectada!.ciudad)).map((r) { final pausada = r['pausada'] == true; return _RouteCard(
                ruta: r, activa: !pausada,
                proximaActivacion: pausada ? (r['tagPausada'] ?? '🚧 Próximamente') : '',
                onTap: pausada ? null : () => RuteroNav.push(context, RouteDetailScreen(ruta: r))); }),
            ] else if (_filtroActivo == 'Temporada') ...[
              _SectionHeader(
                titulo: t('🎆 TEMPORADA','🎆 SEASON'),
                subtitulo: '${_rutas.where((r) => r["zona"] == "Temporada").length} ${t("rutas · orden calendario","routes · calendar order")}'),
              const SizedBox(height: 10),
              ...(() {
                // Feria de las Flores siempre primero — ocultar si módulo Feria activo (tab dedicada)
                final rutasTemp = _rutas.where((r) => r['zona'] == 'Temporada'
                  && (_ciudadDetectada == null || (r['ciudad']?.toString() ?? 'Medellín') == _ciudadDetectada!.ciudad)
                  && !(feriaModuloActivo && r['nombre'] == 'FERIA DE LAS FLORES')
                  // Quitar duplicados — solo mostrar FERIA DE LAS FLORES 2026, no las versiones genéricas
                  && r['nombre'] != 'FERIA DE LAS FLORES'
                  ).toList();
                // Ordenar: 1) vigentes hoy, 2) próximas futuras (más cercanas primero), 3) ya pasadas al final
                // FIX: eventos con >180 días se calculan para el año siguiente
                final ahora = DateTime.now();
                rutasTemp.sort((a, b) {
                  DateTime _proximaFecha(Map<String, dynamic> r) {
                    final List? ini = r['temporadaInicio'] as List?;
                    if (ini == null || ini.length < 2) return DateTime(ahora.year + 1);
                    var dt = DateTime(ahora.year, ini[0] as int, ini[1] as int);
                    // Si la fecha ya pasó este año, usar el año siguiente
                    final List? fin = r['temporadaFin'] as List?;
                    final dtFin = fin != null && fin.length == 2
                      ? DateTime(ahora.year, fin[0] as int, fin[1] as int, 23, 59)
                      : dt;
                    if (dtFin.isBefore(ahora)) dt = DateTime(ahora.year + 1, ini[0] as int, ini[1] as int);
                    return dt;
                  }
                  int _prioridad(Map<String, dynamic> r) {
                    if (_rutaActiva(r)) return 0; // vigente hoy
                    final List? fin = r['temporadaFin'] as List?;
                    if (fin != null && fin.length == 2) {
                      final dtFin = DateTime(ahora.year, fin[0] as int, fin[1] as int, 23, 59);
                      if (dtFin.isBefore(ahora)) return 2; // ya pasó este año
                    }
                    return 1; // próxima
                  }
                  final pa = _prioridad(a);
                  final pb = _prioridad(b);
                  if (pa != pb) return pa.compareTo(pb);
                  // ordenTemporada 99 = siempre al final
                  final oA = a['ordenTemporada'] as int? ?? 50;
                  final oB = b['ordenTemporada'] as int? ?? 50;
                  if (oA == 99 || oB == 99) return oA.compareTo(oB);
                  // Mismo grupo: ordenar por fecha más cercana
                  if (pa == 2) return _proximaFecha(a).compareTo(_proximaFecha(b));
                  return _proximaFecha(a).compareTo(_proximaFecha(b));
                });
                return rutasTemp.map((r) {
                  final pausada = r['pausada'] == true;
                  final activa = !pausada && _rutaActiva(r);
                  return Column(children: [
                    // Contador regresivo solo para Feria de las Flores
                    if (r['mostrarContador'] == true)
                      _FeriaCountdownWidget(),
                    _RouteCard(
                      ruta: r, activa: activa,
                      proximaActivacion: pausada ? (r['tagPausada'] ?? '🚧 Próximamente') : _proximaActivacion(r),
                      diasParaActivacion: _diasParaActivacion(r),
                      onTap: activa ? () => RuteroNav.push(context, RouteDetailScreen(ruta: r)) : null),
                  ]);
                });
              })(),
              const SizedBox(height: 20),

            ] else if (_filtroActivo == 'Comida Urbana') ...[
              _SectionHeader(
                titulo: t('🍟 COMIDA URBANA','🍟 STREET FOOD'),
                subtitulo: '${_rutas.where((r) => r["zona"] == "Comida Urbana").length} ${t("rutas · Street Food MDE","routes · Street Food MDE")}'),
              const SizedBox(height: 10),
              ..._rutas.where((r) => r['zona'] == 'Comida Urbana' && (_ciudadDetectada == null || (r['ciudad']?.toString() ?? 'Medellín') == _ciudadDetectada!.ciudad)).map((r) { final pausada = r['pausada'] == true; return _RouteCard(
                ruta: r, activa: !pausada,
                proximaActivacion: pausada ? (r['tagPausada'] ?? '🚧 Próximamente') : '',
                onTap: pausada ? null : () => RuteroNav.push(context, RouteDetailScreen(ruta: r))); }),
            ] else if (_filtroActivo == 'Eventos') ...[
              _SectionHeader(
                titulo: t('🎪 EVENTOS','🎪 EVENTS'),
                subtitulo: '${_rutas.where((r) => r["zona"] == "Eventos").length} ${t("eventos · activos por fecha","events · active by date")}'),
              const SizedBox(height: 10),
              ..._rutas.where((r) => r['zona'] == 'Eventos').map((r) => _RouteCard(
                ruta: r, activa: false,
                proximaActivacion: _proximaActivacion(r),
                diasParaActivacion: _diasParaActivacion(r),
                onTap: _rutaActivaEvento(r) ? () => RuteroNav.push(context, RouteDetailScreen(ruta: r)) : null)),
            ] else if (_filtroActivo == 'Creadores') ...[
              _SectionHeader(
                titulo: t('🎬 CREADORES','🎬 CREATORS'),
                subtitulo: t('Exploradores que muestran Medellín en terreno real','Explorers who show Medellín in the field')),
              const SizedBox(height: 10),
              StreamBuilder<QuerySnapshot>(
                stream: FirebaseFirestore.instance.collection('colaboradores').where('activo', isEqualTo: true).snapshots(),
                builder: (ctx, snap) {
                  final lista = (snap.hasData && snap.data!.docs.isNotEmpty)
                    ? snap.data!.docs.map((d) {
                        final data = d.data() as Map<String, dynamic>;
                        Color color = kGreen;
                        try { color = Color(int.parse((data['color']?.toString() ?? '#2D5A1B').replaceAll('#', '0xFF'))); } catch (_) {}
                        return _Colaborador(
                          nombre: data['nombre']?.toString() ?? '',
                          handle: data['handle']?.toString() ?? '',
                          plataforma: data['plataforma']?.toString() ?? 'YouTube',
                          descripcion: data['descripcion']?.toString() ?? '',
                          descripcionEN: data['descripcionEN']?.toString() ?? '',
                          emoji: data['emoji']?.toString() ?? '🎬',
                          urlCanal: data['urlCanal']?.toString() ?? '',
                          rutaVinculada: data['rutaVinculada']?.toString() ?? '',
                          rutaVinculadaEN: data['rutaVinculadaEN']?.toString() ?? '',
                          color: color,
                        );
                      }).toList()
                    : kColaboradores;
                  return Column(children: [
                    ...lista.map((c) => GestureDetector(
                      onTap: () => RuteroNav.push(context, ColaboradoresScreen()),
                      child: Container(
                        margin: const EdgeInsets.only(bottom: 12),
                        padding: const EdgeInsets.all(14),
                        decoration: BoxDecoration(
                          color: kCard, borderRadius: BorderRadius.circular(14),
                          border: Border.all(color: c.color.withOpacity(0.3))),
                        child: Row(children: [
                          Container(width: 52, height: 52,
                            decoration: BoxDecoration(shape: BoxShape.circle, color: Colors.white,
                              border: Border.all(color: c.color.withOpacity(0.4), width: 2)),
                            child: ClipOval(child: c.logoAsset != null
                              ? Image.asset(c.logoAsset!, fit: BoxFit.cover)
                              : Center(child: Text(c.emoji, style: const TextStyle(fontSize: 24))))),
                          const SizedBox(width: 12),
                          Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                            Text(c.nombre, style: const TextStyle(color: kText, fontSize: 14, fontWeight: FontWeight.w800)),
                            Text(c.handle, style: TextStyle(color: c.color, fontSize: 11, fontWeight: FontWeight.w600)),
                            const SizedBox(height: 4),
                            Text(c.plataforma, style: TextStyle(color: kTextMuted.withOpacity(0.6), fontSize: 10)),
                          ])),
                          Icon(Icons.arrow_forward_ios, color: c.color.withOpacity(0.5), size: 14),
                        ])))),
                    const SizedBox(height: 8),
                    GestureDetector(
                      onTap: () => RuteroNav.push(context, const ColaboradoresScreen()),
                      child: Text(t('Ver perfil completo →', 'See full profile →'),
                        style: const TextStyle(color: kGreen, fontSize: 11, fontWeight: FontWeight.w700))),
                  ]);
