/// Widget de Dato Curioso (¿Sabías que?)
class CuriosidadCard extends StatelessWidget {
  final String sitioNombre;
  const CuriosidadCard({super.key, required this.sitioNombre});

  @override
  Widget build(BuildContext context) {
    // Primero hardcoded, fallback a Firestore sitiosDetalle
    final data = kCuriosidadesPorSitio[sitioNombre] ?? RutasService().getCuriosidad(sitioNombre);
    if (data == null) return const SizedBox();
    final texto = kLang == 'en' ? (data['en'] ?? data['es'] ?? '') : (data['es'] ?? '');
    if (texto.isEmpty) return const SizedBox();
    return Container(
      margin: const EdgeInsets.only(bottom: 12),
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: kGold.withOpacity(0.10),
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: kGold.withOpacity(0.35)),
      ),
      child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
        const Text('💡', style: TextStyle(fontSize: 24)),
        const SizedBox(width: 10),
        Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Text(t('¿Sabías que...?', 'Did you know?'),
            style: const TextStyle(color: kGold, fontSize: 11,
              fontWeight: FontWeight.w800, letterSpacing: 1.3)),
          const SizedBox(height: 4),
          Text(texto, style: const TextStyle(color: kText, fontSize: 13, height: 1.4)),
        ])),
      ]),
    );
  }
}

/// Widget de Mini-Reto
class RetoCard extends StatefulWidget {
  final String sitioNombre;
  final VoidCallback? onCompletado;
  const RetoCard({super.key, required this.sitioNombre, this.onCompletado});

  @override
  State<RetoCard> createState() => _RetoCardState();
}

class _RetoCardState extends State<RetoCard> {
  bool _completado = false;

  @override
  Widget build(BuildContext context) {
    // Primero hardcoded, fallback a Firestore sitiosDetalle
    final data = kRetosPorSitio[widget.sitioNombre] ?? RutasService().getReto(widget.sitioNombre);
    if (data == null) return const SizedBox();
    final reto = kLang == 'en' ? (data['reto_en'] ?? data['reto_es']) : data['reto_es'];
    final puntos = data['puntos'] ?? 10;
    final emoji = data['emoji'] ?? '🎯';

    return Container(
      margin: const EdgeInsets.only(bottom: 12),
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        gradient: LinearGradient(
          colors: _completado
            ? [kGreen.withOpacity(0.2), kGreen.withOpacity(0.05)]
            : [kOrchid.withOpacity(0.15), kOrchid.withOpacity(0.03)]),
        borderRadius: BorderRadius.circular(12),
        border: Border.all(
          color: _completado ? kGreen.withOpacity(0.5) : kOrchid.withOpacity(0.4),
          width: 1.5,
        ),
      ),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          Text(emoji, style: const TextStyle(fontSize: 22)),
          const SizedBox(width: 8),
          Text(t('MINI-RETO', 'MINI-CHALLENGE'),
            style: TextStyle(color: _completado ? kGreen : kOrchid,
              fontSize: 11, fontWeight: FontWeight.w800, letterSpacing: 1.5)),
          const Spacer(),
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
            decoration: BoxDecoration(
              color: (_completado ? kGreen : kOrchid).withOpacity(0.2),
              borderRadius: BorderRadius.circular(10)),
            child: Text('+$puntos pts',
              style: TextStyle(color: _completado ? kGreen : kOrchid,
                fontSize: 11, fontWeight: FontWeight.w800)),
          ),
        ]),
        const SizedBox(height: 8),
        Text(reto, style: const TextStyle(color: kText, fontSize: 14, height: 1.4)),
        const SizedBox(height: 10),
        GestureDetector(
          onTap: _completado ? null : () {
            setState(() => _completado = true);
            widget.onCompletado?.call();
            ScaffoldMessenger.of(context).showSnackBar(SnackBar(
              backgroundColor: kGreen,
              content: Text(t('🎉 ¡Reto completado! +$puntos puntos',
                              '🎉 Challenge completed! +$puntos points')),
              duration: const Duration(seconds: 2)));
          },
          child: Container(
            padding: const EdgeInsets.symmetric(vertical: 10),
            decoration: BoxDecoration(
              color: _completado ? kGreen : kOrchid,
              borderRadius: BorderRadius.circular(10)),
            child: Row(mainAxisAlignment: MainAxisAlignment.center, children: [
              Text(_completado ? '✅' : '🎯', style: const TextStyle(fontSize: 16)),
              const SizedBox(width: 8),
              Text(_completado
                  ? t('COMPLETADO', 'COMPLETED')
                  : t('MARCAR COMO COMPLETADO', 'MARK AS COMPLETED'),
                style: const TextStyle(color: Colors.white, fontSize: 12,
                  fontWeight: FontWeight.w900, letterSpacing: 1.2)),
            ]),
          ),
        ),
      ]),
    );
  }
}

/// Widget de Trivia (pregunta con opciones)
class TriviaCard extends StatefulWidget {
  final String sitioNombre;
  final VoidCallback? onAcertado;
  const TriviaCard({super.key, required this.sitioNombre, this.onAcertado});

  @override
  State<TriviaCard> createState() => _TriviaCardState();
}

class _TriviaCardState extends State<TriviaCard> {
  int? _seleccion;
  bool _respondido = false;

  @override
  Widget build(BuildContext context) {
    final data = kTriviasPorSitio[widget.sitioNombre];
    if (data == null) return const SizedBox();
    final pregunta = kLang == 'en' ? (data['pregunta_en'] ?? data['pregunta_es']) : data['pregunta_es'];
    final opciones = (kLang == 'en' ? data['opciones_en'] : data['opciones_es']) as List;
    final correcta = (data['correcta'] as int?) ?? 0;
    final puntos = data['puntos'] ?? 10;

    return Container(
      margin: const EdgeInsets.only(bottom: 12),
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: kDark3,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: kAccent.withOpacity(0.4), width: 1.5),
      ),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          const Text('🤔', style: TextStyle(fontSize: 22)),
          const SizedBox(width: 8),
          Text(t('TRIVIA', 'TRIVIA'),
            style: const TextStyle(color: kAccent, fontSize: 11,
              fontWeight: FontWeight.w800, letterSpacing: 1.5)),
          const Spacer(),
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
            decoration: BoxDecoration(
              color: kAccent.withOpacity(0.2),
              borderRadius: BorderRadius.circular(10)),
            child: Text('+$puntos pts',
              style: const TextStyle(color: kAccent, fontSize: 11, fontWeight: FontWeight.w800)),
          ),
        ]),
        const SizedBox(height: 10),
        Text(pregunta, style: const TextStyle(color: kText, fontSize: 14, height: 1.4)),
        const SizedBox(height: 12),
        ...List.generate(opciones.length, (i) {
          final esCorrecta = i == correcta;
          final esSeleccionada = _seleccion == i;
          Color bg = Colors.white.withOpacity(0.04);
          Color border = Colors.white.withOpacity(0.1);
          if (_respondido) {
            if (esCorrecta) { bg = kGreen.withOpacity(0.2); border = kGreen; }
            else if (esSeleccionada) { bg = Colors.red.withOpacity(0.15); border = Colors.red.withOpacity(0.5); }
          }
          return GestureDetector(
            onTap: _respondido ? null : () {
              setState(() { _seleccion = i; _respondido = true; });
              if (esCorrecta) widget.onAcertado?.call();
              ScaffoldMessenger.of(context).showSnackBar(SnackBar(
                backgroundColor: esCorrecta ? kGreen : Colors.red.shade700,
                content: Text(esCorrecta
                  ? t('✅ ¡Correcto! +$puntos puntos', '✅ Correct! +$puntos points')
                  : t('❌ Casi — la respuesta correcta está marcada', '❌ Close — correct answer is marked')),
                duration: const Duration(seconds: 3)));
            },
            child: Container(
              margin: const EdgeInsets.only(bottom: 6),
              padding: const EdgeInsets.all(10),
              decoration: BoxDecoration(
                color: bg, borderRadius: BorderRadius.circular(8),
                border: Border.all(color: border)),
              child: Row(children: [
                Container(width: 22, height: 22,
                  decoration: BoxDecoration(shape: BoxShape.circle,
                    border: Border.all(color: kTextMuted),
                    color: _respondido && esCorrecta ? kGreen : Colors.transparent),
                  child: _respondido && esCorrecta
                    ? const Icon(Icons.check, color: Colors.white, size: 14)
                    : Center(child: Text(String.fromCharCode(65 + i),
                        style: const TextStyle(color: kTextMuted, fontSize: 11, fontWeight: FontWeight.w700))),
                ),
                const SizedBox(width: 10),
                Expanded(child: Text(opciones[i].toString(),
                  style: const TextStyle(color: kText, fontSize: 13))),
              ]),
            ),
          );
        }),
      ]),
    );
  }
}

