class SitioInfoScreen extends StatefulWidget {
  final String sitioNombre;
  final String sitioEmoji;
  final int sitioNumero;
  final int totalSitios;
  final Map<String, dynamic> ruta;
  final double latitud;
  final double longitud;
  const SitioInfoScreen({super.key, required this.sitioNombre, required this.sitioEmoji,
    required this.sitioNumero, required this.totalSitios, required this.ruta,
    this.latitud = 0, this.longitud = 0});
  @override
  State<SitioInfoScreen> createState() => _SitioInfoScreenState();
}

class _SitioInfoScreenState extends State<SitioInfoScreen> {
  double? _distanciaMetros;
  bool _cargandoGps = true;
  bool _dentroDelRango = false;
  bool _errorGps = false;  // FIX 13/05/2026: Para indicar fallo de GPS al usuario
  // Radio dinámico: 1° busca override del sitio específico, 2° radio de la ruta, 3° 30m default
  double get _radio {
    // FIX (junio 2026): buscar por nombre + ruta para evitar colisión entre rutas con sitios de mismo nombre.
    final rutaNombre = widget.ruta['nombre']?.toString() ?? '';
    try {
      final sitio = kSitiosMapa.firstWhere(
        (s) => s.nombre == widget.sitioNombre && s.ruta == rutaNombre);
      if (sitio.radioGps != null) return sitio.radioGps!;
    } catch (_) {
      // Fallback: buscar solo por nombre si no hay coincidencia exacta
      try {
        final sitio = kSitiosMapa.firstWhere((s) => s.nombre == widget.sitioNombre);
        if (sitio.radioGps != null) return sitio.radioGps!;
      } catch (_) {}
    }
    // Fallback: radio de la ruta
    return (widget.ruta['radioGps'] as num?)?.toDouble() ?? 30.0;
  }

  @override
  void initState() { super.initState(); _verificarUbicacion(); }

  Future<void> _verificarUbicacion() async {
    // MODO DEMO: simula que siempre estás en el lugar
    if (kModoDemo) {
      await Future.delayed(const Duration(milliseconds: 1200));
      if (mounted) setState(() {
        _distanciaMetros = 18;
        _dentroDelRango = true;
        _cargandoGps = false;
      });
      return;
    }

    // FIX 1 (13/05/2026): Coordenadas (0,0) NO validan
    // Antes: si lat=0 y lng=0 → asumía dentro del rango (BUG)
    // Ahora: si no hay coordenadas configuradas, NO valida y muestra error
    if (widget.latitud == 0 && widget.longitud == 0) {
      if (mounted) setState(() {
        _cargandoGps = false;
        _dentroDelRango = false;
        _errorGps = true;
      });
      return;
    }

    try {
      LocationPermission p = await Geolocator.checkPermission();
      if (p == LocationPermission.denied) p = await Geolocator.requestPermission();
      if (p == LocationPermission.deniedForever) {
        setState(() { _cargandoGps = false; _dentroDelRango = false; });
        return;
      }
      final pos = await Geolocator.getCurrentPosition(desiredAccuracy: LocationAccuracy.high);
      final dist = Geolocator.distanceBetween(pos.latitude, pos.longitude, widget.latitud, widget.longitud);
      if (mounted) setState(() {
        _distanciaMetros = dist;
        _dentroDelRango = dist <= _radio;
        _cargandoGps = false;
        _errorGps = false;
      });
    } catch (e) {
      // FIX 2 (13/05/2026): Si GPS falla, NO valida (fail-safe)
      // Antes: catch ponía _dentroDelRango = true (BUG GRAVE)
      // Ahora: si hay error, NO valida y marca _errorGps para mostrar UI clara
      debugPrint('⚠️ Error GPS al verificar ubicación: $e');
      if (mounted) setState(() {
        _cargandoGps = false;
        _dentroDelRango = false;
        _errorGps = true;
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    final Color acento = kRutaColor(widget.ruta['acento'], kGreen);
    return Scaffold(
      backgroundColor: kDark2,
      body: Column(children: [
        // ── Header compacto con botón de regreso y contador ──
        Container(
          decoration: BoxDecoration(
            color: kDark2,
            border: Border(bottom: BorderSide(color: acento.withOpacity(0.15)))),
          child: SafeArea(
            bottom: false,
            child: Padding(
              padding: const EdgeInsets.fromLTRB(12, 8, 16, 12),
              child: Column(children: [
                Row(children: [
                  GestureDetector(
                    onTap: () => Navigator.pop(context),
                    child: Container(width: 38, height: 38,
                      decoration: BoxDecoration(
                        color: Colors.white.withOpacity(0.08),
                        shape: BoxShape.circle,
                        border: Border.all(color: acento.withOpacity(0.3))),
                      child: const Center(child: Text('←',
                        style: TextStyle(color: kText, fontSize: 16, fontWeight: FontWeight.w700))))),
                  const SizedBox(width: 12),
                  Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                    Text(rNombre(widget.ruta),
                      style: TextStyle(
                        fontFamily: 'PlayfairDisplay',
                        fontSize: 13, color: acento,
                        fontWeight: FontWeight.w700),
                      maxLines: 1, overflow: TextOverflow.ellipsis),
                    const SizedBox(height: 2),
                    Text('${t("Sitio","Spot")} ${widget.sitioNumero} ${t("de","of")} ${widget.totalSitios}',
                      style: const TextStyle(color: kTextMuted, fontSize: 11)),
                  ])),
                  // Badge sitio
                  Container(
                    padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
                    decoration: BoxDecoration(
                      color: acento.withOpacity(0.15),
                      borderRadius: BorderRadius.circular(20),
                      border: Border.all(color: acento.withOpacity(0.4))),
                    child: Row(mainAxisSize: MainAxisSize.min, children: [
                      Text(widget.sitioEmoji, style: const TextStyle(fontSize: 16)),
                      const SizedBox(width: 4),
                      Text('${widget.sitioNumero}/${widget.totalSitios}',
                        style: TextStyle(
                          fontFamily: 'SpaceGrotesk',
                          fontSize: 11, color: acento, fontWeight: FontWeight.w700)),
                    ])),
                ]),
                const SizedBox(height: 10),
                // Barra de progreso de sitios
                ClipRRect(borderRadius: BorderRadius.circular(3),
                  child: LinearProgressIndicator(
                    value: widget.totalSitios > 0 ? (widget.sitioNumero - 1) / widget.totalSitios : 0,
                    backgroundColor: Colors.white.withOpacity(0.06),
                    valueColor: AlwaysStoppedAnimation<Color>(acento),
                    minHeight: 3)),
              ])))),
        Expanded(child: SingleChildScrollView(
          padding: const EdgeInsets.all(24),
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text(widget.sitioNombre,
              style: const TextStyle(
                fontFamily: 'PlayfairDisplay',
                fontSize: 28, fontWeight: FontWeight.w900,
                color: kText, height: 1.1)),
            const SizedBox(height: 12),
            // ── Foto del sitio eliminada intencionalmente (21/05/2026)
            // El turista descubre la fachada del lugar por sí mismo — es parte
            // de la experiencia y la sorpresa. Sin costo de Google Places API.
            const SizedBox(height: 4),

            // ── Avatar con narración del sitio actual ──
            if (tipsService.containsKey(widget.sitioNombre))
              AvatarTip(
                mensaje: tipsService.getTip(widget.sitioNombre),
                pose: 'tip',
                autoClose: false,
                onCerrar: null),
            if (!tipsService.containsKey(widget.sitioNombre))
              AvatarTip(
                mensaje: t('¡Llegaste a ${widget.sitioNombre}! Explora el lugar y toma la foto para validar tu visita. 📸', 'You made it to ${widget.sitioNombre}! Explore and take a photo to validate your visit. 📸'),
                pose: 'señalando',
                autoClose: false,
                onCerrar: null),

            const SizedBox(height: 16),

            // ── 🎮 GAMIFICACIÓN ──
            CuriosidadCard(sitioNombre: widget.sitioNombre),
            TipSensorialCard(sitioNombre: widget.sitioNombre),
            RetoCard(sitioNombre: widget.sitioNombre),
            TriviaCard(sitioNombre: widget.sitioNombre),

            // ── ALIADOS DE ESTE SITIO ──
            Builder(builder: (_) {
              final aliados = AliadosService().aliadosParaSitio(
                widget.ruta['nombre']?.toString() ?? '',
                widget.sitioNombre);
              if (aliados.isEmpty) return const SizedBox.shrink();
              return Column(children: [
                const SizedBox(height: 16),
                ...aliados.map((a) => Padding(
                  padding: const EdgeInsets.only(bottom: 10),
                  child: _AliadoRutaCard(
                    aliado: a,
                    nombreRuta: widget.ruta['nombre']?.toString()))),
              ]);
            }),

            const SizedBox(height: 16),
            Container(padding: const EdgeInsets.all(16),
              decoration: BoxDecoration(color: kCard, borderRadius: BorderRadius.circular(14),
                border: Border.all(color: acento.withOpacity(0.2))),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Row(children: [const Text('📍', style: TextStyle(fontSize: 18)), const SizedBox(width: 8),
                  Text(tComoLlegar, style: const TextStyle(color: kTextMuted, fontSize: 11, letterSpacing: 2))]),
                const SizedBox(height: 8),
                Text(t('Dirígete a ${widget.sitioNombre}. Una vez estés en el lugar, toma la foto para validar.', 'Head to ${widget.sitioNombre}. Once you are there, take a photo to validate.'),
                  style: const TextStyle(color: kText, fontSize: 13, height: 1.5)),
                // FIX UX (16/05/2026): Botón "CÓMO LLEGAR (Google Maps)" eliminado de aquí.
                // Anteriormente estaba al final de esta tarjeta de info, duplicando la
                // función con el botón gigante de la pantalla anterior.
                // Ahora vive ÚNICAMENTE en la card del sitio activo (_SiteItem),
                // junto al botón "VALIDAR SITIO" en layout horizontal.
                // El turista ya pulsó "VALIDAR SITIO" para llegar aquí, así que esta
                // pantalla queda solo para la validación con foto + GPS.
              ])),
            const SizedBox(height: 12),
            Container(padding: const EdgeInsets.all(16),
              decoration: BoxDecoration(color: kCard, borderRadius: BorderRadius.circular(14),
                border: Border.all(color: Colors.white.withOpacity(0.06))),
              child: Row(children: [
                const Text('🚗', style: TextStyle(fontSize: 22)),
                const SizedBox(width: 12),
                Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Text(tTransporte, style: const TextStyle(color: kTextMuted, fontSize: 10)),
                  Text(widget.ruta['transporte'] ?? '', style: const TextStyle(color: kText, fontSize: 13, fontWeight: FontWeight.w600)),
                ])),
              ])),
            const SizedBox(height: 12),
            _cargandoGps
              ? Container(padding: const EdgeInsets.all(14),
                  decoration: BoxDecoration(color: kCard, borderRadius: BorderRadius.circular(14),
                    border: Border.all(color: Colors.white.withOpacity(0.08))),
                  child: Row(children: [
                    SizedBox(width: 18, height: 18, child: CircularProgressIndicator(strokeWidth: 2, color: acento)),
                    const SizedBox(width: 12),
                    Text(tVerificandoUbic, style: const TextStyle(color: kTextMuted, fontSize: 13)),
                  ]))
              : Container(padding: const EdgeInsets.all(14),
                  decoration: BoxDecoration(
                    color: _dentroDelRango ? kGreen.withOpacity(0.1) : kAccent.withOpacity(0.1),
                    borderRadius: BorderRadius.circular(14),
                    border: Border.all(color: _dentroDelRango ? kGreen.withOpacity(0.4) : kAccent.withOpacity(0.4))),
                  child: Row(children: [
                    Text(_dentroDelRango ? '✅' : (_errorGps ? '⚠️' : '📍'), style: const TextStyle(fontSize: 20)),
                    const SizedBox(width: 10),
                    Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                      // FIX 4 (13/05/2026): Mensajes claros según estado del GPS
                      Text(_dentroDelRango
                          ? t('¡Estás en el lugar!',"You're at the spot!")
                          : _errorGps
                            ? t('Error de GPS','GPS Error')
                            : t('Aún no estás en el lugar',"You're not there yet"),
                        style: TextStyle(
                          color: _dentroDelRango ? kGreen : (_errorGps ? const Color(0xFFE24B4A) : kAccent),
                          fontSize: 13,
                          fontWeight: FontWeight.w700)),
                      const SizedBox(height: 2),
                      Text(_dentroDelRango && _distanciaMetros != null
                          ? t('A ${_distanciaMetros!.toInt()}m — puedes validar', 'At ${_distanciaMetros!.toInt()}m — you can validate')
                          : _errorGps
                            ? t('Activa GPS, espera unos segundos y reintenta', 'Enable GPS, wait a few seconds and retry')
                            : _distanciaMetros != null
                              ? t('Estás a ${_distanciaMetros!.toInt()}m · necesitas menos de ${_radio.toInt()}m', 'You are ${_distanciaMetros!.toInt()}m away · need less than ${_radio.toInt()}m')
                              : t('Verificando ubicación...', 'Verifying location...'),
                        style: const TextStyle(color: kTextMuted, fontSize: 11)),
                    ])),
                    if (!_dentroDelRango)
                      GestureDetector(
                        onTap: () { setState(() { _cargandoGps = true; _errorGps = false; }); _verificarUbicacion(); },
                        child: Container(padding: const EdgeInsets.all(6),
                          decoration: BoxDecoration(color: kCard, borderRadius: BorderRadius.circular(8)),
                          child: const Icon(Icons.refresh, color: kTextMuted, size: 16))),
                  ])),
            const SizedBox(height: 28),
            GestureDetector(
              // FIX 3 (13/05/2026): Re-verificar GPS antes de abrir la cámara
              // El botón está protegido por (!_cargandoGps && _dentroDelRango),
              // pero adicionalmente re-verificamos al momento del toque para
              // evitar que GPS desactualizado permita validación falsa.
              onTap: (!_cargandoGps && _dentroDelRango) ? () async {
                // ── CONVERSIÓN (junio 2026): usuario sin cuenta → mostrar BottomSheet ──
                if (AuthService.currentUser == null) {
                  final decision = await mostrarBottomSheetConversion(context);
                  if (!context.mounted) return;
                  if (decision == true) {
                    await Navigator.of(context).push(
                      MaterialPageRoute(builder: (_) => const RegisterScreen()));
                    return;
                  } else if (decision == false) {
                    await Navigator.of(context).push(
                      MaterialPageRoute(builder: (_) => const LoginScreen()));
                    return;
                  }
                  // decision == null → eligió "Continuar sin guardar" → sigue adelante
                }
                // ── FIN CONVERSIÓN ──

                // Si NO está en modo demo, re-verificar GPS justo antes
                if (!kModoDemo) {
                  setState(() { _cargandoGps = true; });
                  await _verificarUbicacion();
                  if (!_dentroDelRango && context.mounted) {
                    final mensajeError = _errorGps
                      ? t('📍 No pudimos verificar tu ubicación. Activa GPS y reintenta.',
                          '📍 We couldn\'t verify your location. Enable GPS and retry.')
                      : t('📍 No estás en el lugar exacto. Acércate al sitio.',
                          '📍 You\'re not at the exact location. Get closer to the site.');
                    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
                      content: Text(mensajeError),
                      backgroundColor: const Color(0xFFE24B4A),
                      duration: const Duration(seconds: 4),
                    ));
                    return;
                  }
                }
                if (!context.mounted) return;
                final ok = await Navigator.of(context).push<bool>(MaterialPageRoute(
                  builder: (_) => CameraScreen(sitioNombre: widget.sitioNombre, sitioEmoji: widget.sitioEmoji,
                    sitioNumero: widget.sitioNumero, totalSitios: widget.totalSitios, ruta: widget.ruta)));
                if (ok == true && context.mounted) Navigator.of(context).pop(true);
              } : null,
              child: AnimatedContainer(
                duration: const Duration(milliseconds: 300),
                width: double.infinity,
                padding: EdgeInsets.symmetric(vertical: _dentroDelRango ? 20 : 16),
                decoration: BoxDecoration(
                  gradient: LinearGradient(colors: _dentroDelRango
                    ? [acento, acento.withOpacity(0.8)]
                    : [kTextMuted.withOpacity(0.4), kTextMuted.withOpacity(0.3)]),
                  borderRadius: BorderRadius.circular(16),
                  boxShadow: _dentroDelRango ? [
                    BoxShadow(color: acento.withOpacity(0.4), blurRadius: 24, offset: const Offset(0, 8)),
                    BoxShadow(color: acento.withOpacity(0.2), blurRadius: 40),
                  ] : []),
                child: Column(mainAxisSize: MainAxisSize.min, children: [
                  Text(
                    _cargandoGps ? '🔍' :
                    _dentroDelRango ? '📷' :
                    _errorGps ? '⚠️' : '📍',
                    style: TextStyle(fontSize: _dentroDelRango ? 28 : 22)),
                  const SizedBox(height: 4),
                  Text(
                    _cargandoGps ? t('VERIFICANDO UBICACIÓN...','VERIFYING LOCATION...') :
                    _dentroDelRango ? t('TOMAR FOTO Y VALIDAR','TAKE PHOTO & VALIDATE') :
                    _errorGps ? t('REINTENTAR GPS','RETRY GPS') :
                    t('ACÉRCATE AL SITIO','HEAD TO THE SPOT'),
                    textAlign: TextAlign.center,
                    style: TextStyle(
                      fontFamily: 'Inter',
                      fontSize: _dentroDelRango ? 15 : 13,
                      fontWeight: FontWeight.w800,
                      color: Colors.white,
                      letterSpacing: 1.5)),
                ]))),
            const SizedBox(height: 80),
          ]),
        )),
      ]),
    );
  }
}

// ─────────────────────────────────────────
//  CAMERA SCREEN
// ─────────────────────────────────────────
class CameraScreen extends StatefulWidget {
  final String sitioNombre;
  final String sitioEmoji;
  final int sitioNumero;
  final int totalSitios;
  final Map<String, dynamic> ruta;

  final VoidCallback? onValidado;

  const CameraScreen({
    super.key,
    this.sitioNombre = 'Siguiente sitio',
    this.sitioEmoji = '📍',
    this.sitioNumero = 1,
    this.totalSitios = 1,
    required this.ruta,
    this.onValidado,
  });

  @override
  State<CameraScreen> createState() => _CameraScreenState();
}

class _CameraScreenState extends State<CameraScreen> with SingleTickerProviderStateMixin {
  late AnimationController _scanCtrl;
  late Animation<double> _scanAnim;
  bool _validando = false;
  bool _subiendo = false;
  File? _fotoTomada;
  final ImagePicker _picker = ImagePicker();
  bool _mostrarTipAvatar = false;
  String _tipActual = '';
  String _poseActual = 'camara';

  @override
  void initState() {
    super.initState();
    _scanCtrl = AnimationController(vsync: this, duration: const Duration(seconds: 2))..repeat();
    _scanAnim = Tween<double>(begin: 0, end: 1).animate(_scanCtrl);
    // El usuario toca el botón de cámara — no se abre automáticamente
    // Flujo: detalles del sitio → botón 📷 → cámara
  }

  @override
  void dispose() { _scanCtrl.dispose(); super.dispose(); }

  // Abrir cámara real
  Future<void> _abrirCamara() async {
    // ── CONVERSIÓN (junio 2026): segunda línea de defensa para usuarios sin cuenta ──
    if (AuthService.currentUser == null) {
      final decision = await mostrarBottomSheetConversion(context);
      if (!context.mounted) return;
      if (decision == true) {
        await Navigator.of(context).push(
          MaterialPageRoute(builder: (_) => const RegisterScreen()));
        return;
      } else if (decision == false) {
        await Navigator.of(context).push(
          MaterialPageRoute(builder: (_) => const LoginScreen()));
        return;
      }
      // decision == null → continuar sin cuenta (foto no se guardará)
    }
    // ── FIN CONVERSIÓN ──

    // Bloquear orientación a vertical antes de abrir cámara
    await SystemChrome.setPreferredOrientations([DeviceOrientation.portraitUp]);
    try {
      final XFile? foto = await _picker.pickImage(
        source: ImageSource.camera,
        imageQuality: 85,
        maxWidth: 900,
        maxHeight: 1600,
        preferredCameraDevice: CameraDevice.rear,
      );
      if (foto != null && mounted) {
        // Mostrar preview antes de confirmar
        final confirmar = await _mostrarPreviewFoto(File(foto.path));
        // Restaurar orientaciones normales
        await SystemChrome.setPreferredOrientations([
          DeviceOrientation.portraitUp,
          DeviceOrientation.landscapeLeft,
          DeviceOrientation.landscapeRight,
        ]);
        if (confirmar == true && mounted) {
          setState(() => _fotoTomada = File(foto.path));
          await _guardarEnGaleria(File(foto.path));
          await _validarFoto();
        }
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text(t('Error al abrir cámara: $e','Error opening camera: $e')),
            backgroundColor: Colors.red));
      }
    }
  }

  // Componer foto con avatar y guardar en galería
  Future<void> _guardarEnGaleria(File foto) async {
    try {
      final fotoBytes = await foto.readAsBytes();
      final fotoImg = await decodeImageFromList(fotoBytes);

      // Cargar logo real PNG
      final logoData = await rootBundle.load('assets/images/logo_rutero_badge.png');
      final logoBytes = logoData.buffer.asUint8List();
      final logoImg = await decodeImageFromList(logoBytes);

      final recorder = ui.PictureRecorder();
      final canvas = Canvas(recorder);
      final w = fotoImg.width.toDouble();
      final h = fotoImg.height.toDouble();

      // Foto de fondo
      canvas.drawImage(fotoImg, Offset.zero, Paint());

      // ── MARCO INFERIOR ──
      final marcoH = h * 0.20;
      final marcoRect = Rect.fromLTWH(0, h - marcoH, w, marcoH);

      // Fondo oscuro sólido + gradiente superior
      canvas.drawRect(marcoRect, Paint()..color = const Color(0xF00A0F08));
      final gradPaint = Paint()..shader = LinearGradient(
        begin: Alignment.topCenter, end: Alignment.bottomCenter,
        colors: [Colors.transparent, const Color(0xF00A0F08)],
      ).createShader(Rect.fromLTWH(0, h - marcoH - 40, w, 40));
      canvas.drawRect(Rect.fromLTWH(0, h - marcoH - 40, w, 40), gradPaint);

      // Logo PNG — esquina inferior izquierda
      final logoH = marcoH * 0.65;
      final logoW = logoImg.width * (logoH / logoImg.height);
      final logoY = h - marcoH + (marcoH - logoH) / 2;
      canvas.drawImageRect(
        logoImg,
        Rect.fromLTWH(0, 0, logoImg.width.toDouble(), logoImg.height.toDouble()),
        Rect.fromLTWH(20, logoY, logoW, logoH),
        Paint());

      // Línea separadora vertical
      canvas.drawLine(
        Offset(logoW + 30, h - marcoH + 14),
        Offset(logoW + 30, h - 14),
        Paint()..color = const Color(0xFFD4AF7A).withOpacity(0.4)..strokeWidth = 1);

      final textX = logoW + 42;

      // Tamaños escalados al tamaño real de la imagen (w puede ser 2000-4000px)
      final escala = w / 1080; // base de referencia 1080px

      // Nombre del sitio
      final tpSitio = TextPainter(
        text: TextSpan(text: widget.sitioNombre,
          style: TextStyle(color: Colors.white, fontSize: 52 * escala,
            fontWeight: FontWeight.w800)),
        textDirection: TextDirection.ltr,
        maxLines: 1, ellipsis: '...');
      tpSitio.layout(maxWidth: w - textX - 20);
      tpSitio.paint(canvas, Offset(textX, h - marcoH + marcoH * 0.12));

      // Nombre ruta
      final rutaNombre = widget.ruta['nombre']?.toString() ?? 'Rutero MDE';
      final tpRuta = TextPainter(
        text: TextSpan(text: rutaNombre,
          style: TextStyle(color: const Color(0xFFD4AF7A).withOpacity(0.9), fontSize: 34 * escala,
            fontWeight: FontWeight.w600)),
        textDirection: TextDirection.ltr,
        maxLines: 1, ellipsis: '...');
      tpRuta.layout(maxWidth: w - textX - 20);
      tpRuta.paint(canvas, Offset(textX, h - marcoH + marcoH * 0.48));

      // Fecha
      final fecha = '${DateTime.now().day}/${DateTime.now().month}/${DateTime.now().year}';
      final tpFecha = TextPainter(
        text: TextSpan(text: fecha,
          style: TextStyle(color: Colors.white.withOpacity(0.6), fontSize: 26 * escala)),
        textDirection: TextDirection.ltr);
      tpFecha.layout();
      tpFecha.paint(canvas, Offset(textX, h - marcoH + marcoH * 0.72));

      // Exportar
      final img = await recorder.endRecording().toImage(fotoImg.width, fotoImg.height);
      final byteData = await img.toByteData(format: ui.ImageByteFormat.png);
      final composedBytes = byteData!.buffer.asUint8List();

      // Guardar temporalmente y luego mover a galería del sistema
      final dir = await getApplicationDocumentsDirectory();
      final ruteroDir = Directory('${dir.path}/RuteroMDE');
      if (!await ruteroDir.exists()) await ruteroDir.create(recursive: true);
      final timestamp = DateTime.now().millisecondsSinceEpoch;
      final archivo = File('${ruteroDir.path}/rutero_$timestamp.png');
      await archivo.writeAsBytes(composedBytes);

      // Guardar en galería del sistema (aparece en Fotos del celular)
      await Gal.putImage(archivo.path, album: 'Rutero MDE');

      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Row(children: [
            const Text('📸', style: TextStyle(fontSize: 18)),
            const SizedBox(width: 8),
            Text(tFotoGuardada, style: const TextStyle(fontWeight: FontWeight.w600)),
          ]),
          backgroundColor: kGreen,
          duration: const Duration(seconds: 3)));
      }
    } catch (e) {
      debugPrint('Error guardando foto compuesta: $e');
    }
  }

