class _SitioMapa {
  final String nombre, emoji;
  final LatLng posicion;
  final String ruta;
  final Color color;
  final bool visitado;
  final double? radioGps; // override opcional del radio de la ruta
  const _SitioMapa({required this.nombre, required this.emoji, required this.posicion,
    required this.ruta, required this.color, this.visitado = false, this.radioGps});
}

