class MisFotosScreen extends StatefulWidget {
  const MisFotosScreen({super.key});
  @override
  State<MisFotosScreen> createState() => _MisFotosScreenState();
}

class _MisFotosScreenState extends State<MisFotosScreen> {
  String _filtroRuta = 'Todas';
  final List<String> _rutas = ['Todas'];

  @override
  Widget build(BuildContext context) {
    final user = AuthService.currentUser;
    return Scaffold(
      backgroundColor: kDark2,
      body: Column(children: [
        // Header
        Container(
          decoration: const BoxDecoration(
            gradient: LinearGradient(begin: Alignment.topLeft, end: Alignment.bottomRight,
              colors: [Color(0xFF0A1A0A), Color(0xFF0F2010)])),
          child: SafeArea(child: Padding(
            padding: const EdgeInsets.fromLTRB(20, 16, 20, 20),
            child: Column(children: [
              Row(children: [
                GestureDetector(onTap: () => Navigator.of(context, rootNavigator: false).pop(),
                  child: Container(width: 36, height: 36,
                    decoration: BoxDecoration(color: Colors.black.withOpacity(0.4), shape: BoxShape.circle),
                    child: const Center(child: Text('←', style: TextStyle(color: kText, fontSize: 16))))),
                const SizedBox(width: 14),
                Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Text(tMisFotos, style: const TextStyle(fontSize: 20, fontWeight: FontWeight.w900,
                    color: kText, letterSpacing: 2)),
                  Text(tRecuerdosRutas, style: const TextStyle(fontSize: 11, color: kTextMuted)),
                ]),
              ]),
            ])))),

        // Contenido
        Expanded(
          child: user == null
            ? Center(child: Column(mainAxisSize: MainAxisSize.min, children: [
                const Text('🔒', style: TextStyle(fontSize: 48)),
                const SizedBox(height: 12),
                Text(tIniciarSesionFotos,
                  style: const TextStyle(color: kTextMuted, fontSize: 14)),
              ]))
            : StreamBuilder<QuerySnapshot>(
                stream: FirebaseFirestore.instance
                  .collection('usuarios').doc(user.uid)
                  .collection('fotos')
                  .orderBy('fecha', descending: true)
                  .snapshots(),
                builder: (ctx, snap) {
                  if (snap.connectionState == ConnectionState.waiting)
                    return const Center(child: CircularProgressIndicator(color: kGreen));
                  final fotos = snap.data?.docs ?? [];
                  if (fotos.isEmpty)
                    return Center(child: Column(mainAxisSize: MainAxisSize.min, children: [
                      const Text('📸', style: TextStyle(fontSize: 64)),
                      const SizedBox(height: 16),
                      Text(t('Aún no tienes fotos', 'No photos yet'),
                        style: const TextStyle(color: kText, fontSize: 18, fontWeight: FontWeight.w700)),
                      const SizedBox(height: 8),
                      Text(t('Completa sitios en tus rutas\npara coleccionar recuerdos',
                             'Complete spots on your routes\nto collect memories'),
                        textAlign: TextAlign.center,
                        style: const TextStyle(color: kTextMuted, fontSize: 13, height: 1.5)),
                      const SizedBox(height: 24),
                      GestureDetector(
                        onTap: () { if (Navigator.canPop(context)) Navigator.pop(context); },
                        child: Container(
                          padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 12),
                          decoration: BoxDecoration(
                            gradient: const LinearGradient(colors: [kGreen, kGold]),
                            borderRadius: BorderRadius.circular(20)),
                          child: const Text('EXPLORAR RUTAS',
                            style: TextStyle(color: Colors.white, fontSize: 13, fontWeight: FontWeight.w800)))),
                    ]));

                  // Construir lista de rutas para filtro
                  final rutasSet = {'Todas', ...fotos.map((f) => (f.data() as Map)['ruta']?.toString() ?? '')};
                  final rutasList = rutasSet.where((r) => r.isNotEmpty).toList();

                  final fotosFiltradas = _filtroRuta == 'Todas'
                    ? fotos
                    : fotos.where((f) => (f.data() as Map)['ruta'] == _filtroRuta).toList();

                  return Column(children: [
                    // Stats bar
                    Container(
                      padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 12),
                      color: kCard,
                      child: Row(children: [
                        _MapStat(valor: '${fotos.length}', label: 'Fotos', color: kGreen),
                        Container(width: 1, height: 30, color: Colors.white.withOpacity(0.08),
                          margin: const EdgeInsets.symmetric(horizontal: 16)),
                        _MapStat(valor: '${rutasList.length - 1}', label: 'Rutas', color: kGold),
                        Container(width: 1, height: 30, color: Colors.white.withOpacity(0.08),
                          margin: const EdgeInsets.symmetric(horizontal: 16)),
                        _MapStat(valor: '${fotosFiltradas.length}', label: 'Mostrando', color: kOrchid),
                      ])),

                    // Filtro por ruta
                    if (rutasList.length > 2)
                      Container(
                        height: 44,
                        color: kDark3,
                        child: ListView.builder(
                          scrollDirection: Axis.horizontal,
                          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
                          itemCount: rutasList.length,
                          itemBuilder: (_, i) {
                            final ruta = rutasList[i];
                            final activo = _filtroRuta == ruta;
                            return GestureDetector(
                              onTap: () => setState(() => _filtroRuta = ruta),
                              child: Container(
                                margin: const EdgeInsets.only(right: 8),
                                padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 4),
                                decoration: BoxDecoration(
                                  color: activo ? kGreen.withOpacity(0.2) : Colors.transparent,
                                  borderRadius: BorderRadius.circular(20),
                                  border: Border.all(
                                    color: activo ? kGreen : Colors.white.withOpacity(0.12))),
                                child: Text(ruta == 'Todas' ? 'Todas' : ruta.split(' ').first,
                                  style: TextStyle(
                                    color: activo ? kGreen : kTextMuted,
                                    fontSize: 11, fontWeight: activo ? FontWeight.w700 : FontWeight.normal))));
                          })),

                    // Grid de fotos
                    Expanded(
                      child: GridView.builder(
                        padding: const EdgeInsets.all(12),
                        gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
                          crossAxisCount: 2,
                          crossAxisSpacing: 10,
                          mainAxisSpacing: 10,
                          childAspectRatio: 0.75),
                        itemCount: fotosFiltradas.length,
                        itemBuilder: (ctx, i) {
                          final data = fotosFiltradas[i].data() as Map<String, dynamic>;
                          final url = data['url']?.toString();
                          final sitio = data['sitio']?.toString() ?? '';
                          final ruta = data['ruta']?.toString() ?? '';
                          final emoji = data['emoji']?.toString() ?? '📍';
                          final rutaEmoji = data['rutaEmoji']?.toString() ?? '🗺️';
                          final acento = data['acento'] != null
                            ? Color((data['acento'] as int?) ?? 0)
                            : kGreen;
                          final fecha = (data['fecha'] as Timestamp?)?.toDate();

                          return GestureDetector(
                            onTap: () => _verFotoCompleta(context, data),
                            child: Container(
                              decoration: BoxDecoration(
                                color: kCard,
                                borderRadius: BorderRadius.circular(16),
                                border: Border.all(color: acento.withOpacity(0.3)),
                                boxShadow: [BoxShadow(
                                  color: Colors.black.withOpacity(0.3), blurRadius: 8)]),
                              child: ClipRRect(
                                borderRadius: BorderRadius.circular(16),
                                child: Stack(fit: StackFit.expand, children: [
                                  // Foto: URL real > archivo local > placeholder
                                  url != null
                                    ? Image.network(url, fit: BoxFit.cover,
                                        loadingBuilder: (_, child, progress) => progress == null
                                          ? child
                                          : Container(color: kDark3,
                                              child: const Center(child: CircularProgressIndicator(
                                                color: kGreen, strokeWidth: 2))),
                                        errorBuilder: (_, __, ___) {
                                          final localPath = data['localPath']?.toString();
                                          return localPath != null && File(localPath).existsSync()
                                            ? Image.file(File(localPath), fit: BoxFit.cover)
                                            : _placeholderFoto(emoji, acento);
                                        })
                                    : (() {
                                        final localPath = data['localPath']?.toString();
                                        return localPath != null && File(localPath).existsSync()
                                          ? Image.file(File(localPath), fit: BoxFit.cover)
                                          : _placeholderFoto(emoji, acento);
                                      })(),
                                  // Overlay inferior
                                  Positioned(bottom: 0, left: 0, right: 0,
                                    child: Container(
                                      padding: const EdgeInsets.all(10),
                                      decoration: const BoxDecoration(
                                        gradient: LinearGradient(
                                          begin: Alignment.bottomCenter, end: Alignment.topCenter,
                                          colors: [Colors.black87, Colors.transparent])),
                                      child: Column(crossAxisAlignment: CrossAxisAlignment.start,
                                        mainAxisSize: MainAxisSize.min, children: [
                                        Text('$emoji $sitio',
                                          style: const TextStyle(color: kText, fontSize: 11,
                                            fontWeight: FontWeight.w700),
                                          maxLines: 1, overflow: TextOverflow.ellipsis),
                                        Text('$rutaEmoji ${ruta.split(' ').take(2).join(' ')}',
                                          style: TextStyle(color: acento, fontSize: 9),
                                          maxLines: 1, overflow: TextOverflow.ellipsis),
                                        if (fecha != null)
                                          Text('${fecha.day}/${fecha.month}/${fecha.year}',
                                            style: const TextStyle(color: kTextMuted, fontSize: 9)),
                                      ]))),
                                  // Badge compartir
                                  Positioned(top: 8, right: 8,
                                    child: GestureDetector(
                                      onTap: () => _compartirFoto(data),
                                      child: Container(width: 30, height: 30,
                                        decoration: BoxDecoration(
                                          color: Colors.black.withOpacity(0.6),
                                          shape: BoxShape.circle),
                                        child: const Center(
                                          child: Text('↗️', style: TextStyle(fontSize: 14)))))),
                                ]))));
                        })),
                  ]);
                })),
      ]),
    );
  }

  Widget _placeholderFoto(String emoji, Color acento) {
    return Container(
      decoration: BoxDecoration(
        gradient: LinearGradient(
          begin: Alignment.topLeft, end: Alignment.bottomRight,
          colors: [acento.withOpacity(0.3), kDark3])),
      child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [
        Text(emoji, style: const TextStyle(fontSize: 40)),
        const SizedBox(height: 8),
        const Text('📸 Foto demo', style: TextStyle(color: kTextMuted, fontSize: 10)),
      ]));
  }

  void _verFotoCompleta(BuildContext context, Map<String, dynamic> data) {
    final url = data['url']?.toString();
    final sitio = data['sitio']?.toString() ?? '';
    final ruta = data['ruta']?.toString() ?? '';
    final emoji = data['emoji']?.toString() ?? '📍';
    final acento = data['acento'] != null ? Color((data['acento'] as int?) ?? 0) : kGreen;

    showDialog(context: context, builder: (_) => Dialog(
      backgroundColor: Colors.transparent,
      child: Column(mainAxisSize: MainAxisSize.min, children: [
        ClipRRect(
          borderRadius: BorderRadius.circular(20),
          child: Stack(children: [
            (() {
              final localPath = data['localPath']?.toString();
              if (url != null) {
                return Image.network(url, fit: BoxFit.cover,
                  errorBuilder: (_, __, ___) => localPath != null && File(localPath).existsSync()
                    ? Image.file(File(localPath), fit: BoxFit.cover)
                    : _placeholderFoto(emoji, acento));
              } else if (localPath != null && File(localPath).existsSync()) {
                return Image.file(File(localPath), fit: BoxFit.cover);
              }
              return _placeholderFoto(emoji, acento);
            })(),
            // Info overlay
            Positioned(bottom: 0, left: 0, right: 0,
              child: Container(
                padding: const EdgeInsets.all(16),
                decoration: const BoxDecoration(
                  gradient: LinearGradient(
                    begin: Alignment.bottomCenter, end: Alignment.topCenter,
                    colors: [Colors.black87, Colors.transparent])),
                child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Text('$emoji $sitio',
                    style: const TextStyle(color: kText, fontSize: 16, fontWeight: FontWeight.w800)),
                  Text(ruta, style: TextStyle(color: acento, fontSize: 12)),
                ]))),
          ])),
        const SizedBox(height: 12),
        Row(mainAxisAlignment: MainAxisAlignment.center, children: [
          // Compartir
          GestureDetector(
            onTap: () { Navigator.of(context, rootNavigator: true).pop(); _compartirFoto(data); },
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 10),
              decoration: BoxDecoration(
                color: kGreen.withOpacity(0.2),
                borderRadius: BorderRadius.circular(20),
                border: Border.all(color: kGreen.withOpacity(0.5))),
              child: const Text('↗️ Compartir',
                style: TextStyle(color: kGreen, fontWeight: FontWeight.w700)))),
          const SizedBox(width: 12),
          // Cerrar
          GestureDetector(
            onTap: () => Navigator.of(context, rootNavigator: true).pop(),
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 10),
              decoration: BoxDecoration(
                color: Colors.white.withOpacity(0.08),
                borderRadius: BorderRadius.circular(20)),
              child: const Text('✕ Cerrar',
                style: TextStyle(color: kTextMuted, fontWeight: FontWeight.w700)))),
        ]),
      ])));
  }

  Future<void> _compartirFoto(Map<String, dynamic> data) async {
    final sitio  = data['sitio']?.toString() ?? '';
    final ruta   = data['ruta']?.toString() ?? '';
    final url    = data['url']?.toString();
    final localPath = data['localPath']?.toString();

    try {
      // Texto de acompañamiento
      final texto = t(
        '📍 Visité $sitio en la ruta "$ruta" con Rutero MDE 🌿\n'
        '¡Descubre Medellín de forma gamificada! 🗺️\nrutero-mde.web.app',
        '📍 I visited $sitio on the "$ruta" route with Rutero MDE 🌿\n'
        'Discover Medellín in a gamified way! 🗺️\nrutero-mde.web.app');

      // Intentar compartir imagen si existe localmente
      if (localPath != null && File(localPath).existsSync()) {
        await Share.shareXFiles(
          [XFile(localPath)],
          text: texto,
          subject: 'Rutero MDE — $sitio');
        return;
      }

      // Si solo tiene URL (Firebase Storage) — descargar temporalmente y compartir
      if (url != null && url.isNotEmpty) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text(t('Preparando foto...', 'Preparing photo...')),
          backgroundColor: kGreen,
          duration: const Duration(seconds: 2)));

        final response = await http.get(Uri.parse(url));
        if (response.statusCode == 200) {
          final tempDir = await getTemporaryDirectory();
          final tempFile = File(
            '${tempDir.path}/rutero_${sitio.replaceAll(' ', '_')}_${DateTime.now().millisecondsSinceEpoch}.jpg');
          await tempFile.writeAsBytes(response.bodyBytes);
          await Share.shareXFiles(
            [XFile(tempFile.path)],
            text: texto,
            subject: 'Rutero MDE — $sitio');
          return;
        }
      }

      // Fallback: compartir solo texto
      await Share.share(texto, subject: 'Rutero MDE — $sitio');

    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text(t('Error al compartir: $e', 'Error sharing: $e')),
          backgroundColor: kAccent,
          duration: const Duration(seconds: 3)));
      }
    }
  }
}

