// ─────────────────────────────────────────────────────────────────────────
//  🌹 FERIA DE LAS FLORES — Countdown Widget
//  Muestra contador regresivo hasta el 31 de julio de 2026
//  + botón para ver los sitios que se van a visitar (abrebocas)
// ─────────────────────────────────────────────────────────────────────────
class _FeriaCountdownWidget extends StatefulWidget {
  const _FeriaCountdownWidget();
  @override
  State<_FeriaCountdownWidget> createState() => _FeriaCountdownWidgetState();
}

class _FeriaCountdownWidgetState extends State<_FeriaCountdownWidget> {
  late Timer _timer;
  Duration _restante = Duration.zero;
  bool _mostrarSitios = false;

  // Fecha de inicio Feria de las Flores 2026
  static final DateTime _fechaFeria = DateTime(2026, 7, 31, 8, 0, 0);

  static const List<String> _sitiosFeria = [
    '🎤 Parque de los Deseos — Trova y música',
    '🌸 Orquideorama — Exposición de flores',
    '🌾 Finca Silletera — Santa Elena',
    '🎪 Plaza Mayor — Exhibición de silletas',
    '🌺 Placita de Flórez — Plaza de Flores',
    '🎭 Avenida Guayabal — Desfile Silleteros',
    '🎵 Parques del Río — Tablado musical',
    '🏟️ Atanasio Girardot — Autos Clásicos',
  ];

  @override
  void initState() {
    super.initState();
    _actualizar();
    _timer = Timer.periodic(const Duration(seconds: 1), (_) => _actualizar());
  }

  void _actualizar() {
    final ahora = DateTime.now();
    final diff = _fechaFeria.difference(ahora);
    if (mounted) setState(() => _restante = diff.isNegative ? Duration.zero : diff);
  }

  @override
  void dispose() {
    _timer.cancel();
    super.dispose();
  }

  String _pad(int n) => n.toString().padLeft(2, '0');

  @override
  Widget build(BuildContext context) {
    final dias   = _restante.inDays;
    final horas  = _restante.inHours % 24;
    final mins   = _restante.inMinutes % 60;
    final segs   = _restante.inSeconds % 60;
    final yaEsFeria = _restante == Duration.zero;

    return Container(
      margin: const EdgeInsets.only(bottom: 16),
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        gradient: const LinearGradient(
          colors: [Color(0xFF1A0A10), Color(0xFF2A1020)],
          begin: Alignment.topLeft, end: Alignment.bottomRight),
        borderRadius: BorderRadius.circular(18),
