class _RouteCard extends StatelessWidget {
  final Map<String, dynamic> ruta;
  final VoidCallback? onTap;
  final bool activa;
  final String proximaActivacion;
  final int diasParaActivacion;
  const _RouteCard({required this.ruta, this.onTap, this.activa = true,
    this.proximaActivacion = '', this.diasParaActivacion = 0});

  @override
  Widget build(BuildContext context) {
    final Color acento = activa ? kRutaColor(ruta['acento'], kGold) : kTextMuted;
    final bool esImperdible = ruta['imperdible'] == true || ruta['zona'] == 'Ciudad';
    final int puntos = ((ruta['sitios'] ?? 5) as int) * 30;

    return GestureDetector(
      onTap: onTap,
      child: Container(
        margin: const EdgeInsets.only(bottom: 16),
        height: 240,
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(20),
          boxShadow: [BoxShadow(
            color: acento.withOpacity(activa ? 0.25 : 0.08),
            blurRadius: 20, offset: const Offset(0, 6))]),
        child: ClipRRect(
          borderRadius: BorderRadius.circular(20),
          child: Stack(fit: StackFit.expand, children: [
            // Imagen de fondo o gradiente
