class _SiteItem extends StatelessWidget {
  final int numero; final String nombre, desc, estado, emoji;
  final Color acento;
  final VoidCallback? onValidar;
  final bool rutaComprada;
  final double? distanciaMetros; // distancia GPS al sitio activo
  final String? rutaNombre; // FIX (junio 2026): para resolver colisión de nombres en kSitiosMapa
  const _SiteItem({required this.numero, required this.nombre, required this.desc,
    required this.estado, required this.emoji, required this.acento,
    this.onValidar, this.rutaComprada = false, this.distanciaMetros, this.rutaNombre});
  @override
  Widget build(BuildContext context) {
    Color numColor; Color textColor; String icono;
    switch (estado) {
      case 'done': numColor = kGreen; textColor = kText; icono = '✅'; break;
      case 'active': numColor = acento; textColor = acento; icono = '📷'; break;
      default: numColor = kDark3; textColor = kTextMuted; icono = '🔒';
    }
    // FIX UX (16/05/2026): Obtener coords del sitio activo para botón "Cómo llegar"
    // FIX (junio 2026): filtrar por rutaNombre para evitar colisión de nombres entre rutas.
    double lat = 0, lng = 0;
    if (estado == 'active') {
      try {
        final rn = rutaNombre ?? '';
        final s = rn.isNotEmpty
          ? kSitiosMapa.firstWhere((s) => s.nombre == nombre && s.ruta == rn,
              orElse: () => kSitiosMapa.firstWhere((s) => s.nombre == nombre))
          : kSitiosMapa.firstWhere((s) => s.nombre == nombre);
        lat = s.posicion.latitude;
        lng = s.posicion.longitude;
      } catch (_) {
        // Sitio no está en kSitiosMapa — buscar en gpsSitios o sitiosDetalle de Firestore
        try {
          final rutaData = RutasService().rutas.firstWhere(
            (r) => r['nombre']?.toString() == (rutaNombre ?? ''), orElse: () => {});

          // 1. Buscar en gpsSitios
          final gpsRaw = rutaData['gpsSitios'];
          final gpsList = gpsRaw is List ? gpsRaw : <dynamic>[];
          final gps = gpsList.firstWhere(
            (g) => g is Map && g['nombre']?.toString() == nombre, orElse: () => null);
          if (gps != null && gps is Map) {
            lat = (gps['lat'] as num?)?.toDouble() ?? 0;
            lng = (gps['lng'] as num?)?.toDouble() ?? 0;
          }

          // 2. Si no encontró en gpsSitios, buscar en sitiosDetalle (Feria, Vive Centro, etc.)
          if (lat == 0 && lng == 0) {
            final detalle = parseSitiosDetalle(rutaData['sitiosDetalle']);
            final sitio = detalle.firstWhere(
              (s) => s is Map && s['nombre']?.toString() == nombre, orElse: () => null);
            if (sitio != null && sitio is Map) {
              lat = (sitio['lat'] as num?)?.toDouble() ?? 0;
              lng = (sitio['lng'] as num?)?.toDouble() ?? 0;
            }
          }

          // 3. Buscar en kFeriaRutasCompletas si sigue sin encontrar
          if (lat == 0 && lng == 0) {
            for (final feriaRuta in kFeriaRutasCompletas) {
              final feriaDetalle = parseSitiosDetalle(feriaRuta['sitiosDetalle']);
              final sitio = feriaDetalle.firstWhere(
                (s) => s is Map && s['nombre']?.toString() == nombre, orElse: () => null);
              if (sitio != null && sitio is Map) {
                lat = (sitio['lat'] as num?)?.toDouble() ?? 0;
                lng = (sitio['lng'] as num?)?.toDouble() ?? 0;
                break;
              }
            }
          }
        } catch (_) {}
      }

    }
    return Container(margin: const EdgeInsets.only(bottom: 10), padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(color: kCard, borderRadius: BorderRadius.circular(12),
        border: Border.all(color: estado == 'active' ? acento.withOpacity(0.3) : Colors.white.withOpacity(0.05))),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          // ── Cuadro número de orden + distancia (21/05/2026) ──
          Container(
            width: 48, height: 48,
            decoration: BoxDecoration(
              color: estado == 'done'
                ? kGreen.withOpacity(0.12)
                : estado == 'active'
                  ? kGold.withOpacity(0.12)
                  : Colors.white.withOpacity(0.04),
              borderRadius: BorderRadius.circular(10),
              border: Border.all(color: estado == 'done'
                ? kGreen.withOpacity(0.3)
                : estado == 'active'
                  ? kGold.withOpacity(0.4)
                  : Colors.white.withOpacity(0.08))),
            child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [
              Text(
                numero.toString().padLeft(2, '0'),
                style: TextStyle(
                  fontSize: 16, fontWeight: FontWeight.w500, height: 1,
                  color: estado == 'done'
                    ? kGreen
                    : estado == 'active'
                      ? kGold
                      : const Color(0xFF555555))),
              const SizedBox(height: 2),
              Text(
                estado == 'active' && distanciaMetros != null
                  ? (distanciaMetros! < 1000
                      ? '${distanciaMetros!.toInt()} m'
                      : '${(distanciaMetros! / 1000).toStringAsFixed(1)} km')
                  : estado == 'done' ? 'listo' : '—',
                style: TextStyle(
                  fontSize: 9, fontWeight: FontWeight.w500,
                  color: estado == 'done'
                    ? kGreen.withOpacity(0.6)
                    : estado == 'active'
                      ? kGold
                      : const Color(0xFF444444))),
            ])),
          const SizedBox(width: 12),
          Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text(nombre, style: TextStyle(color: textColor, fontSize: 13, fontWeight: FontWeight.w600)),
            Text(desc, style: const TextStyle(color: kTextMuted, fontSize: 11)),
          ])),
          Text(icono, style: const TextStyle(fontSize: 18)),
        ]),
        // FIX UX (16/05/2026): Botones "Cómo llegar" + "Validar Sitio" SOLO en sitio ACTIVO
        // FIX (8/07/2026): En kModoLanzamiento, mostrar botón sin esperar rutaComprada
        if (estado == 'active' && (rutaComprada || kModoLanzamiento)) ...[
          const SizedBox(height: 10),
          Row(children: [
            // Botón izquierda: CÓMO LLEGAR (Google Maps)
            Expanded(
              child: GestureDetector(
                onTap: (lat != 0 && lng != 0) ? () async {
                  final url = Uri.parse(
                    'https://www.google.com/maps/dir/?api=1&destination=$lat,$lng&travelmode=driving');
                  try {
                    final ok = await launchUrl(url, mode: LaunchMode.externalApplication);
                    if (!ok && context.mounted) {
                      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
                        backgroundColor: Colors.red.shade700,
                        content: Text(t('No se pudo abrir Google Maps', 'Could not open Google Maps'))));
                    }
                  } catch (e) {
                    if (context.mounted) {
                      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
                        backgroundColor: Colors.red.shade700,
                        content: Text(t('Error al abrir Maps: $e', 'Error opening Maps: $e'))));
                    }
                  }
                } : null,
                child: Container(
                  padding: const EdgeInsets.symmetric(vertical: 10),
                  decoration: BoxDecoration(
                    color: kCard,
                    borderRadius: BorderRadius.circular(10),
                    border: Border.all(color: acento.withOpacity(0.6), width: 1.5),
                  ),
                  child: Row(mainAxisAlignment: MainAxisAlignment.center, children: [
                    const Text('🗺️', style: TextStyle(fontSize: 14)),
                    const SizedBox(width: 6),
                    Flexible(
                      child: Text(t('CÓMO LLEGAR', 'GET DIRECTIONS'),
                        style: TextStyle(color: acento, fontSize: 11,
                          fontWeight: FontWeight.w800, letterSpacing: 0.5),
                        overflow: TextOverflow.ellipsis),
                    ),
                  ]),
                ),
              ),
            ),
            const SizedBox(width: 8),
            // Botón derecha: VALIDAR SITIO (abre SitioInfoScreen)
            Expanded(
              child: GestureDetector(
                onTap: onValidar,
                child: Container(
                  padding: const EdgeInsets.symmetric(vertical: 10),
                  decoration: BoxDecoration(
                    gradient: LinearGradient(colors: [acento, acento.withOpacity(0.7)]),
                    borderRadius: BorderRadius.circular(10),
                    boxShadow: [BoxShadow(color: acento.withOpacity(0.3), blurRadius: 10, offset: const Offset(0, 4))],
                  ),
                  child: Row(mainAxisAlignment: MainAxisAlignment.center, children: [
                    const Text('📷', style: TextStyle(fontSize: 14)),
                    const SizedBox(width: 6),
                    Flexible(
                      child: Text(t('VALIDAR SITIO', 'VALIDATE SPOT'),
                        style: const TextStyle(color: Colors.white, fontSize: 11,
                          fontWeight: FontWeight.w800, letterSpacing: 0.5),
                        overflow: TextOverflow.ellipsis),
                    ),
                  ]),
                ),
              ),
            ),
          ]),
        ],
      ]));
  }
}

