// ════════════════════════════════════════════════════════════════
//  _CardCodigoAliado — Sprint 1: Aliado Final con código de canje
// ════════════════════════════════════════════════════════════════
//  Card que aparece en RewardScreen cuando el turista valida un
//  sitio que es Aliado Final. Muestra:
//    - Nombre y emoji del aliado
//    - Beneficio prometido (descuento, regalo)
//    - Código único grande, copiable
//    - Instrucciones para canje
// ════════════════════════════════════════════════════════════════
class _CardCodigoAliado extends StatelessWidget {
  final AliadoComercial aliado;
  final String codigo;
  const _CardCodigoAliado({required this.aliado, required this.codigo});

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.all(18),
      decoration: BoxDecoration(
        gradient: LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: [kGold.withOpacity(0.18), kOrchid.withOpacity(0.12)],
        ),
        borderRadius: BorderRadius.circular(18),
        border: Border.all(color: kGold.withOpacity(0.5), width: 1.5),
      ),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        // Header
        Row(children: [
          Text(aliado.emoji, style: const TextStyle(fontSize: 28)),
          const SizedBox(width: 10),
          Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text('💎 ${kLang == 'en' ? 'PARTNER REWARD' : 'PREMIO ALIADO'}',
              style: TextStyle(color: kGold, fontSize: 10, fontWeight: FontWeight.w900, letterSpacing: 2)),
            const SizedBox(height: 2),
            Text(aliado.nombre,
              style: const TextStyle(color: kText, fontSize: 16, fontWeight: FontWeight.w800)),
          ])),
        ]),
        const SizedBox(height: 12),

        // Beneficio
        Container(
          padding: const EdgeInsets.all(12),
          decoration: BoxDecoration(
            color: kCard.withOpacity(0.6),
            borderRadius: BorderRadius.circular(10),
          ),
          child: Row(children: [
            const Text('🎁', style: TextStyle(fontSize: 18)),
            const SizedBox(width: 10),
            Expanded(child: Text(
              aliado.beneficio,
              style: const TextStyle(color: kText, fontSize: 13, fontWeight: FontWeight.w600, height: 1.4),
            )),
          ]),
        ),
        const SizedBox(height: 14),

        // Código (lo más prominente)
        Text(
          kLang == 'en' ? 'YOUR CODE' : 'TU CÓDIGO',
          style: TextStyle(color: kTextMuted, fontSize: 9, letterSpacing: 2, fontWeight: FontWeight.w800),
        ),
        const SizedBox(height: 6),
        GestureDetector(
          onTap: () {
            Clipboard.setData(ClipboardData(text: codigo));
            ScaffoldMessenger.of(context).showSnackBar(SnackBar(
              content: Text(kLang == 'en' ? '✅ Code copied!' : '✅ ¡Código copiado!'),
              backgroundColor: kGreen,
              duration: const Duration(seconds: 2),
            ));
          },
          child: Container(
            width: double.infinity,
            padding: const EdgeInsets.symmetric(vertical: 14, horizontal: 12),
            decoration: BoxDecoration(
              color: kDark3,
              borderRadius: BorderRadius.circular(10),
              border: Border.all(color: kGold.withOpacity(0.4), width: 1.5),
            ),
            child: Row(children: [
              Expanded(child: Text(
                codigo,
                style: const TextStyle(
                  color: kGold,
                  fontSize: 18,
                  fontWeight: FontWeight.w900,
                  letterSpacing: 1.5,
                  fontFamily: 'monospace',
                ),
                textAlign: TextAlign.center,
              )),
              const Icon(Icons.copy, color: kGold, size: 18),
            ]),
          ),
        ),
        const SizedBox(height: 10),

        // Instrucciones
        Row(children: [
          const Text('📍', style: TextStyle(fontSize: 12)),
          const SizedBox(width: 6),
          Expanded(child: Text(
            aliado.ubicacion,
            style: const TextStyle(color: kTextMuted, fontSize: 11, height: 1.4),
          )),
        ]),
        const SizedBox(height: 8),
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
          decoration: BoxDecoration(
            color: kGreen.withOpacity(0.12),
            borderRadius: BorderRadius.circular(8),
          ),
          child: Text(
            kLang == 'en'
              ? '💡 Show this code to the partner before paying to get your benefit.'
              : '💡 Muestra este código al aliado antes de pagar para obtener tu beneficio.',
            style: const TextStyle(color: kText, fontSize: 11, height: 1.5),
          ),
        ),
      ]),
    );
  }
}

